window.COURSE_DATA = {"modules":[{"id":"m1","number":"01","title":"数据库技术基础","subtitle":"概念 · 模型 · 体系结构","color":"green"},{"id":"m2","number":"02","title":"关系数据库的理论基础","subtitle":"关系 · 码 · 关系代数","color":"blue"},{"id":"m4","number":"04","title":"SQL 基础","subtitle":"定义 · 查询 · 操纵 · 视图","color":"orange"},{"id":"m5","number":"05","title":"关系数据库规范化","subtitle":"函数依赖 · 候选码 · 范式","color":"purple"},{"id":"m6","number":"06","title":"MySQL 存储程序","subtitle":"变量 · 游标 · 过程 · 函数 · 触发器","color":"pink"},{"id":"m7","number":"07","title":"数据库设计与综合应用","subtitle":"E-R · 关系转换 · 综合题","color":"teal"}],"lessons":[{"id":"db-system","module":"m1","title":"从数据到数据库系统","summary":"分清 DB、DBMS 与 DBS，理解数据库解决的问题。","blocks":[{"type":"text","title":"先想一个选课系统","text":"同一名学生可能选多门课。如果每门课各保存一份学生姓名，改名时就要修改许多文件，遗漏后会产生矛盾。数据库通过共享数据、定义约束和统一管理，把“保存记录”变成可持续的数据管理。数据是描述事物的符号记录；语义说明数据代表什么，例如 93 可以是成绩，也可以是年龄。"},{"type":"table","title":"三个容易混淆的概念","heads":["概念","含义","选课系统中的对应"],"rows":[["DB","长期保存、有组织、可共享的数据集合","学生、课程和选课记录"],["DBMS","定义、查询、更新并管理数据库的软件","MySQL 等关系数据库管理软件"],["DBS","数据库、DBMS、应用、人员和运行环境构成的系统","完整的选课服务"]]},{"type":"text","title":"DBMS 做什么","text":"用 DDL 定义结构，用数据操纵功能查询和修改数据；通过完整性约束、权限、并发控制和备份恢复，维护数据的正确性、安全性和可用性。DBMS 是软件，数据库是被管理的数据，不要互换。"},{"type":"steps","title":"数据管理的发展","items":["人工管理：数据依赖程序，不能集中共享。","文件系统：数据可长期保存，但文件间联系与一致性由应用维护。","数据库系统：数据整体结构化、共享性提高、冗余受控、数据独立性较高。"]},{"type":"tip","text":"共享不意味着任何人都能访问全部数据；共享需要权限与并发控制。"}],"tags":["基础"],"minutes":10},{"id":"three-schema","module":"m1","title":"三级模式与两级映像","summary":"从用户视图、整体逻辑结构到物理存储。","blocks":[{"type":"table","title":"三级模式","heads":["层次","描述内容","例子"],"rows":[["外模式","特定用户看见的局部逻辑结构","学生只能查看自己的成绩"],["模式","数据库整体逻辑结构及约束","Student、Course、SC 的字段与联系"],["内模式","数据物理存储方式与存取路径","记录组织、索引与存储安排"]]},{"type":"text","title":"两级映像为什么存在","text":"外模式／模式映像把用户看到的结构映射到整体结构，支持逻辑独立性；模式／内模式映像把逻辑结构映射到物理存储，支持物理独立性。映像允许某一层变化时，其他层尽量不跟着修改。"},{"type":"table","title":"判断独立性","heads":["变化","应调整的映像","体现"],"rows":[["新增字段，原应用继续使用原视图","外模式／模式映像","逻辑独立性"],["更换存储文件位置、增加存取路径","模式／内模式映像","物理独立性"]]},{"type":"tip","text":"概念设计得到的 E-R 概念模型，与三级模式中的“模式”不是同一个术语层次。"}],"tags":["基础","易混"],"minutes":10},{"id":"data-model","module":"m1","title":"数据模型与 E-R 基本元素","summary":"把现实业务抽象为实体、属性和联系。","blocks":[{"type":"text","title":"模型的层次","text":"概念模型面向业务理解，独立于具体 DBMS；逻辑模型面向数据库组织，例如关系模型；物理模型描述具体存储实现。数据模型包含数据结构、数据操作、完整性约束三个组成部分。"},{"type":"table","title":"E-R 图符号","heads":["元素","含义","传统画法"],"rows":[["实体型","具有相同属性的一类对象，例如学生","矩形"],["属性","对象特征，例如学号、姓名","椭圆"],["联系","实体之间的关联，例如选修","菱形"]]},{"type":"text","title":"辨认实体与属性","text":"需要单独标识、有自己的多项描述、会参与多种联系的对象，通常适合建为实体。电话号码是学生的属性；课程有课程号、名称和学分，并被许多学生选修，适合建为实体。实体型是结构，实体值是一个具体对象。"},{"type":"steps","title":"确定联系基数","items":["1:1：一个 A 至多对应一个 B，反向也如此。","1:n：一个 A 可对应多个 B，但一个 B 至多对应一个 A，例如部门与职工。","m:n：两端都可对应多个对象，例如学生与课程。联系可能有属性，例如选修联系的成绩。"]},{"type":"tip","text":"基数来自题目业务规则。例如“每个教师只教一门课”与“教师可教多门课”会产生不同模型。"}],"tags":["设计","重点"],"minutes":10},{"id":"relation-key","module":"m2","title":"关系、关系模式与各种码","summary":"用最小性准确区分超码、候选码与主码。","blocks":[{"type":"text","title":"关系与模式","text":"关系可以理解为某时刻的一张符合关系模型的表；关系模式描述它的结构与约束，可写为 R(U,F)，U 是属性集合，F 是函数依赖集合。元组对应行，属性对应列，域描述允许取值的集合。关系的度是属性数，基数是元组数。"},{"type":"table","title":"码的区分","heads":["名称","严格含义","例子"],"rows":[["超码","能唯一确定一个元组的属性集合","学号、或学号与姓名组合"],["候选码","不含多余属性的超码","学号；若身份证号唯一且非空，也可候选"],["主码","从候选码中选定的一个","选定学号"],["主属性","属于任一候选码的属性","不能只看选定的主码"],["外码","引用被参照关系候选码的属性组","SC.sno 引用 Student.sno"]]},{"type":"text","title":"关系的性质","text":"理论关系没有重复元组，元组顺序与属性排列顺序不影响关系含义；每个属性值按所采用的模型应是原子的。SQL 查询默认可能保留重复行，需要 DISTINCT 才去重。"},{"type":"tip","text":"外键可以同时属于本表主键。SC 的 (sno,cno) 是复合主键，而 sno、cno 分别是两个外键。不能说“外键一定不是候选码”。"}],"tags":["重点","易混"],"minutes":10},{"id":"integrity","module":"m2","title":"三类完整性约束","summary":"让结构主动拒绝不符合业务规则的数据。","blocks":[{"type":"table","title":"完整性与 SQL 约束","heads":["完整性","要保证的事","SQL"],"rows":[["实体完整性","主码唯一，组成主码的属性都非空","PRIMARY KEY"],["参照完整性","外码有合法的引用目标，或按规则允许为空","FOREIGN KEY ... REFERENCES"],["用户自定义完整性","业务要求的非空、范围、唯一性等","NOT NULL、CHECK、UNIQUE"]]},{"type":"code","title":"选课联系的约束","code":"CREATE TABLE SC (\n  sno VARCHAR(8),\n  cno VARCHAR(4),\n  grade DECIMAL(5,2),\n  CONSTRAINT pk_sc PRIMARY KEY (sno, cno),\n  CONSTRAINT fk_sc_s FOREIGN KEY (sno) REFERENCES Student(sno),\n  CONSTRAINT fk_sc_c FOREIGN KEY (cno) REFERENCES Course(cno),\n  CONSTRAINT ck_grade CHECK (grade BETWEEN 0 AND 100)\n);","dialect":"MySQL 8.0.16+"},{"type":"text","title":"NULL 需要单独思考","text":"CHECK 约束在条件为 TRUE 或 UNKNOWN 时允许数据通过，因而 CHECK(grade BETWEEN 0 AND 100) 仍允许 NULL。未出分可以用 NULL；若要求必须有成绩，还需 NOT NULL。主键已经隐含非空要求。"},{"type":"tip","text":"外键不是“只要两个字段同名就成立”。必须显式定义或在理论模式中明确引用关系。"}],"tags":["建表","重点"],"minutes":10},{"id":"set-algebra","module":"m2","title":"集合运算与笛卡尔积","summary":"计算并、交、差，以及行数和列数。","blocks":[{"type":"table","title":"集合运算","heads":["运算","结果","条件"],"rows":[["R ∪ S","属于 R 或 S 的元组，去重","并相容"],["R ∩ S","同时属于 R 和 S 的元组","并相容"],["R − S","属于 R 但不属于 S 的元组","并相容"],["R × S","R 与 S 的元组两两组合","无需并相容"]]},{"type":"text","title":"并相容","text":"参与并、交、差的两个关系必须有相同的属性数，对应属性的域应相容。差不满足交换律：R − S 通常不同于 S − R。"},{"type":"text","title":"手算一个例子","text":"R(A)={(1),(2)}，S(A)={(2),(3)}。并为 {(1),(2),(3)}，交为 {(2)}，R−S 为 {(1)}。若 T(B)={(x),(y),(z)}，R×T 有 2×3=6 行、1+1=2 列。"},{"type":"code","title":"SQL 中的集合写法","code":"SELECT sno FROM SC WHERE cno = 'C01'\nUNION\nSELECT sno FROM SC WHERE cno = 'C02';","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"UNION 去重，UNION ALL 保留重复。为兼容 MySQL 8.0.16+，集合差可以用 NOT EXISTS；不要依赖较新版本才提供的集合差语法。"}],"tags":["关系代数"],"minutes":10},{"id":"select-project-join","module":"m2","title":"选择、投影与连接","summary":"先确定取哪些行，再确定取哪些列。","blocks":[{"type":"table","title":"三种基本操作","heads":["操作","含义","对应 SQL 思路"],"rows":[["σ条件(R)","选择符合条件的行","WHERE"],["π属性(R)","选择属性列并去重","SELECT DISTINCT"],["R ⋈条件 S","从笛卡尔积选符合条件的元组","JOIN ... ON"]]},{"type":"text","title":"组合表达式","text":"查询年龄小于 20 岁学生的姓名：πsname(σage\u003c20(Student))。先按年龄筛选学生，再投影姓名。若先投影只剩姓名，就失去了判断年龄所需的属性。"},{"type":"text","title":"等值连接与自然连接","text":"等值连接可以比较不同名称的属性，并保留连接两端的列；自然连接在全部同名属性上做等值比较，并合并同名列。自然连接不是随意选择一对同名列。实际 SQL 编程常显式写 JOIN ... ON，避免增加同名列后悄悄改变语义。"},{"type":"code","title":"查学生姓名和已选课程号","code":"SELECT s.sname, sc.cno\nFROM Student s\nJOIN SC sc ON sc.sno = s.sno;","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"理论投影会去重，SQL 的 SELECT 列名默认不去重。两者对应时要补 DISTINCT。"}],"tags":["关系代数","查询"],"minutes":10},{"id":"division","module":"m2","title":"除法与“选修全部课程”","summary":"把“全部”转换成“不存在缺少的那一门”。","blocks":[{"type":"text","title":"除法在问什么","text":"设 R(X,Y) 记录谁拥有哪个 Y，S(Y) 列出要求具备的全部 Y。R÷S 返回这样的 X：对 S 中每个 Y，R 中都有对应的 (X,Y)。例如 R 是选课，S 是必修课程，结果就是选齐必修课程的学生。"},{"type":"steps","title":"手算除法","items":["从 R 中取出 X 的候选值。","逐个 X 检查它对应的 Y 集合。","保留覆盖 S 中全部 Y 的 X。多选额外课程不影响。"]},{"type":"code","title":"双重 NOT EXISTS：没有一门课没选","code":"SELECT s.sno, s.sname\nFROM Student s\nWHERE NOT EXISTS (\n  SELECT 1 FROM Course c\n  WHERE NOT EXISTS (\n    SELECT 1 FROM SC sc\n    WHERE sc.sno = s.sno AND sc.cno = c.cno\n  )\n);","dialect":"MySQL 8.0.16+"},{"type":"text","title":"用边界情况检验","text":"如果课程表为空，对每个学生都不存在一门“没选的课”，所以这条查询返回所有学生。若题目要求课程非空，应额外表达该业务前提。"}],"tags":["综合题","重点"],"minutes":10},{"id":"ddl-types","module":"m4","title":"SQL 分类与数据类型","summary":"使用 MySQL 的字符、数值与日期类型写出建表语句。","blocks":[{"type":"table","title":"SQL 的功能","heads":["类别","常用语句","目的"],"rows":[["DDL","CREATE、ALTER、DROP","定义数据库对象"],["DML","INSERT、UPDATE、DELETE","修改表中数据"],["查询","SELECT","检索数据"],["事务控制","COMMIT、ROLLBACK、SAVEPOINT","控制一组操作的提交与撤销"],["数据控制","GRANT、REVOKE","授权与回收权限"]]},{"type":"table","title":"MySQL 常用类型","heads":["类型","含义","例子"],"rows":[["CHAR(n)","固定长度字符","课程编号"],["VARCHAR(n)","可变长度字符","姓名"],["INT","整数","年龄、数量"],["DECIMAL(p,s)","总位数 p，小数位数 s","DECIMAL(6,2) 可有 4 位整数"],["DATE / DATETIME","仅日期 / 日期与时间","入学日期 / 操作时间"]]},{"type":"code","title":"创建学生和课程表","code":"CREATE TABLE Student (\n  sno VARCHAR(8) PRIMARY KEY,\n  sname VARCHAR(40) NOT NULL,\n  dept VARCHAR(30),\n  age INT CHECK (age BETWEEN 0 AND 120)\n);\nCREATE TABLE Course (\n  cno VARCHAR(4) PRIMARY KEY,\n  cname VARCHAR(60) NOT NULL,\n  credit DECIMAL(3,1) CHECK (credit > 0)\n);","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"整数主键需要自动编号时可用 AUTO_INCREMENT。表和列名用反引号引用，字符串用单引号；CHECK 约束需要 MySQL 8.0.16 或更新版本。"}],"tags":["SQL","建表","重点"],"minutes":10},{"id":"alter-index","module":"m4","title":"修改表与索引","summary":"区分结构变更、数据删除和访问加速。","blocks":[{"type":"code","title":"修改列与命名约束","code":"ALTER TABLE Student ADD COLUMN entrance_date DATE;\nALTER TABLE Student MODIFY COLUMN sname VARCHAR(60) NOT NULL;\nALTER TABLE Student ADD CONSTRAINT uq_student_name UNIQUE (sname);\nALTER TABLE Student DROP INDEX uq_student_name;\nALTER TABLE Student DROP COLUMN entrance_date;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"不要随意把姓名设为唯一","text":"上面的唯一约束仅用于演示语法。若业务允许同名学生，就不能使用该约束。任何约束都应由需求支持。"},{"type":"code","title":"创建和删除索引","code":"CREATE INDEX idx_sc_cno ON SC(cno);\nCREATE UNIQUE INDEX idx_course_name ON Course(cname);\nDROP INDEX idx_course_name ON Course;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"索引的收益与代价","text":"索引通常有利于定位、连接和部分排序，但需要额外空间，并增加插入、删除和更新的维护成本。唯一索引还限制值的唯一性。不要因为某列存在就建索引；应结合高频查询和数据分布。"},{"type":"table","title":"删什么","heads":["语句","影响"],"rows":[["DELETE FROM Student WHERE ...","删除满足条件的行，保留表"],["DROP TABLE Student","删除表对象及其数据"],["ALTER TABLE Student DROP COLUMN ...","删除字段定义"]]},{"type":"tip","text":"InnoDB 要求外键列有可用索引；若没有合适索引会自动创建。主键和唯一约束也由索引支持，但普通索引不保证唯一。"}],"tags":["SQL","索引","易混"],"minutes":10},{"id":"query-filter","module":"m4","title":"单表查询、NULL 与模式匹配","summary":"从 SELECT、WHERE、ORDER BY 写对第一条查询。","blocks":[{"type":"code","title":"筛选、投影与排序","code":"SELECT sno, sname, age\nFROM Student\nWHERE dept = '计算机' AND age \u003c 21\nORDER BY age ASC, sno ASC;","dialect":"MySQL 8.0.16+"},{"type":"table","title":"条件表达式","heads":["目的","写法","注意"],"rows":[["集合成员","cno IN ('C01','C02')","不是 IN ('C01,C02')"],["闭区间","grade BETWEEN 60 AND 100","包含两个端点"],["缺失值","grade IS NULL","不能写 grade = NULL"],["前缀匹配","sname LIKE '张%'","% 匹配任意长度，_ 匹配一个字符"],["匹配普通下划线","code LIKE 'A/_%' ESCAPE '/'","转义后 _ 不再是通配符"]]},{"type":"text","title":"NULL 的三值逻辑","text":"NULL 表示未知或缺失。与 NULL 的普通比较结果为 UNKNOWN，WHERE 只保留 TRUE 的行，所以 grade \u003c> 60 不会选出 NULL 成绩。要包含未出分学生，需要显式加 OR grade IS NULL。"},{"type":"text","title":"逻辑顺序","text":"可按 FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY 理解查询语义。书写顺序仍然以 SELECT 开头。AND 优先于 OR，复杂条件用括号说明意图。"},{"type":"tip","text":"LIKE 的通配符是 % 与 _。判断字符串含数字可写 REGEXP_LIKE(sname, '[0-9]') 或 sname REGEXP '[0-9]'。"}],"tags":["SQL","查询","重点"],"minutes":10},{"id":"aggregate","module":"m4","title":"聚合、GROUP BY 与 HAVING","summary":"分清筛选行和筛选分组，处理没有成绩的情况。","blocks":[{"type":"code","title":"按课程统计已出分成绩","code":"SELECT cno, COUNT(*) AS selected_count,\n       COUNT(grade) AS graded_count,\n       ROUND(AVG(grade), 2) AS avg_grade\nFROM SC\nGROUP BY cno\nHAVING COUNT(grade) >= 2\nORDER BY avg_grade DESC;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"COUNT 与 AVG 的边界","text":"COUNT(*) 统计所有行；COUNT(grade) 只统计 grade 非空的行。AVG、SUM 通常忽略 NULL。没有任何非空成绩时，AVG 与 SUM 返回 NULL，COUNT 返回 0。不要把未出分当作零分，除非题意要求。"},{"type":"text","title":"WHERE 与 HAVING","text":"WHERE 在分组前筛选行，HAVING 在分组后筛选组。查“及格人数至少为 2 的课程”可以先 WHERE grade>=60 再分组；查“平均分至少为 80 的课程”应使用 HAVING AVG(grade)>=80。"},{"type":"code","title":"保留所有课程，即使没人选","code":"SELECT c.cno, c.cname, COUNT(sc.sno) AS n\nFROM Course c LEFT JOIN SC sc ON sc.cno = c.cno\nGROUP BY c.cno, c.cname;","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"外连接后 COUNT(*) 会把空补齐的那一行也计入。统计真实匹配记录应 COUNT(sc.sno)。非聚合输出列应写入 GROUP BY，避免依赖 SQLite 的宽松行为。"}],"tags":["SQL","重点","聚合"],"minutes":10},{"id":"joins","module":"m4","title":"多表连接、外连接与自连接","summary":"先明确连接条件，再考虑要保留哪一端。","blocks":[{"type":"code","title":"学生、选课、课程三表连接","code":"SELECT s.sno, s.sname, c.cname, sc.grade\nFROM Student s\nJOIN SC sc ON sc.sno = s.sno\nJOIN Course c ON c.cno = sc.cno;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"内连接与左外连接","text":"内连接只保留匹配行。LEFT JOIN 保留左表每一行，右表无匹配时用 NULL 补齐。查询“所有学生及其数据库成绩，包括没选的人”要把课程条件放在 ON 中。"},{"type":"code","title":"条件放在 ON 中保留未选课学生","code":"SELECT s.sno, s.sname, sc.grade\nFROM Student s\nLEFT JOIN SC sc ON sc.sno = s.sno AND sc.cno = 'C01';","dialect":"MySQL 8.0.16+"},{"type":"text","title":"为什么不能随便移到 WHERE","text":"若写 WHERE sc.cno='C01'，没有匹配的学生其 sc.cno 为 NULL，被 WHERE 排除，左连接的保留效果就消失了。"},{"type":"code","title":"自连接：课程与先修课程（需 pcno 字段）","code":"SELECT c.cname, p.cname AS prerequisite\nFROM Course c LEFT JOIN Course p ON p.cno = c.pcno;","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"没有连接条件时容易形成笛卡尔积。每增加一张表，都检查连接字段、重复行和是否需要 DISTINCT。"}],"tags":["SQL","连接","重点"],"minutes":10},{"id":"subqueries","module":"m4","title":"子查询、EXISTS 与集合查询","summary":"用子查询回答最大值、超过平均值和没有记录。","blocks":[{"type":"code","title":"保留所有并列最高分","code":"SELECT sno, grade FROM SC\nWHERE cno = 'C01'\n  AND grade = (SELECT MAX(grade) FROM SC WHERE cno = 'C01');","dialect":"MySQL 8.0.16+"},{"type":"code","title":"相关子查询：高于本课程平均分","code":"SELECT sc.sno, sc.cno, sc.grade\nFROM SC sc\nWHERE sc.grade > (\n  SELECT AVG(t.grade) FROM SC t WHERE t.cno = sc.cno\n);","dialect":"MySQL 8.0.16+"},{"type":"code","title":"没有选过任何课的学生","code":"SELECT s.sno, s.sname FROM Student s\nWHERE NOT EXISTS (\n  SELECT 1 FROM SC sc WHERE sc.sno = s.sno\n);","dialect":"MySQL 8.0.16+"},{"type":"text","title":"IN 与 EXISTS","text":"IN 判断一个值是否属于子查询结果集合；EXISTS 只判断子查询是否至少返回一行。相关子查询使用外层当前行的值，例如 sc.sno=s.sno。NOT IN 的子查询若含 NULL，可能让预期记录都无法通过；表达“无匹配”时应仔细处理 NULL，或使用 NOT EXISTS。"},{"type":"tip","text":"最高值题目若没有要求只取一人，要保留并列。不要简单排序后截取第一行。"}],"tags":["SQL","子查询","重点"],"minutes":10},{"id":"dml-transaction","module":"m4","title":"增删改与事务","summary":"把数据操作写清楚，并判断是否提交。","blocks":[{"type":"code","title":"插入、修改与删除","code":"INSERT INTO SC(sno, cno, grade) VALUES ('S05', 'C02', NULL);\nUPDATE SC SET grade = 85 WHERE sno = 'S05' AND cno = 'C02';\nDELETE FROM SC WHERE sno = 'S05' AND cno = 'C02';","dialect":"MySQL 8.0.16+"},{"type":"text","title":"先检查条件范围","text":"UPDATE 与 DELETE 不写 WHERE 会影响全表。正式操作前用相同 WHERE 做 SELECT，检查目标行；在实验区可以随时重置样例库。INSERT 指明列名可避免字段顺序变化造成错位。"},{"type":"code","title":"事务控制的意图","code":"START TRANSACTION;\nSAVEPOINT before_change;\nUPDATE SC SET grade = grade + 2 WHERE grade BETWEEN 0 AND 98;\nROLLBACK TO SAVEPOINT before_change;\nCOMMIT;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"事务由谁提交","text":"InnoDB 支持事务；默认自动提交开启，需用 START TRANSACTION 把一组修改组成事务。COMMIT 确认更改，ROLLBACK 撤销尚未提交的更改。可复用过程通常将提交决定留给调用者。CREATE、ALTER、DROP 等 DDL 通常会隐式提交，不应当作普通 DML 回滚。"}],"tags":["SQL","事务"],"minutes":10},{"id":"views","module":"m4","title":"视图与 WITH CHECK OPTION","summary":"从查询封装到限制可见数据。","blocks":[{"type":"code","title":"创建视图","code":"CREATE VIEW CS_Student AS\nSELECT sno, sname, dept FROM Student\nWHERE dept = '计算机'\nWITH CHECK OPTION;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"视图是什么","text":"视图保存查询定义，提供基表数据的虚拟接口，常用于简化查询和控制暴露的行列。MySQL 普通视图不独立保存一份查询结果。"},{"type":"text","title":"检查选项","text":"WITH CHECK OPTION 要求通过可更新视图插入或修改的数据，仍满足视图条件。例如通过 CS_Student 把 dept 改为“数学”，会违反视图的过滤条件。它不是允许任意复杂视图更新的开关。"},{"type":"text","title":"哪些视图难以更新","text":"含聚合、分组、DISTINCT、UNION 等操作的视图通常不可更新，连接视图也有更新限制。WITH CHECK OPTION 约束可更新视图的写入范围；它不会把不可更新视图变成可更新视图。"},{"type":"code","title":"通过视图查询与删除视图","code":"SELECT sno, sname FROM CS_Student;\nDROP VIEW CS_Student;","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"删除视图不会删除其基表。视图与索引作用不同：视图组织访问接口，索引服务存取效率。"}],"tags":["SQL","视图","重点"],"minutes":10},{"id":"functional-dependency","module":"m5","title":"函数依赖：先写业务规则","summary":"由业务约束判断依赖，不能只看几行样本。","blocks":[{"type":"text","title":"X → Y 的定义","text":"在关系模式的每一个合法关系实例中，只要两个元组的 X 值相同，它们的 Y 值就必须相同，就称 Y 函数依赖于 X。X、Y 都是属性集合。X 可以对应多种其他记录，但不能为同一个 X 产生不同的 Y。"},{"type":"text","title":"从选课业务写依赖","text":"若学号唯一标识学生、课程号唯一标识课程、每名学生对每门课只保留一个成绩，可写：sno→sname,dept；cno→cname,credit；(sno,cno)→grade。若允许重修且保存多次成绩，需要加入学期或考试次数，依赖与码都会变化。"},{"type":"table","title":"平凡与非平凡","heads":["类型","条件","例子"],"rows":[["平凡依赖","Y ⊆ X","(sno,cno) → sno"],["非平凡依赖","Y 不是 X 的子集","sno → sname"]]},{"type":"text","title":"如何反驳一个依赖","text":"只要找到两个合法元组，它们 X 相同而 Y 不同，就能否定 X→Y。相反，几行样本恰好没有冲突，不能证明所有合法实例都满足该依赖。"},{"type":"tip","text":"姓名是否唯一取决于题意。现实中通常允许重名，不应擅自写 sname→sno。"}],"tags":["规范化","重点"],"minutes":10},{"id":"dependency-types","module":"m5","title":"完全依赖、部分依赖与传递依赖","summary":"识别导致 2NF 和 3NF 问题的具体依赖。","blocks":[{"type":"table","title":"三种依赖","heads":["类型","识别方式","例子"],"rows":[["完全函数依赖","X→Y，且任何真子集都不能决定 Y","(sno,cno) 完全决定 grade"],["部分函数依赖","X→Y，但某个真子集已能决定 Y","(sno,cno) 决定 sname，而 sno 已足够"],["传递依赖","通过不是超码的中间属性继续决定非主属性","sno→dept，dept→head"]]},{"type":"text","title":"先确定候选码","text":"判断部分依赖要相对于指定的决定属性集合，范式判断则要检查所有候选码。StudentCourse(sno,sname,cno,grade) 中，若候选码为 (sno,cno)，sname 只依赖 sno，是非主属性对候选码的部分依赖。"},{"type":"text","title":"传递依赖的考试表达","text":"在 Student(sno,dept,head) 中，假设一个学生属于一个系，一个系只有一位系主任，且系不能唯一确定学生，则 sno→dept→head 导致系主任信息在多个学生行上重复。应把 Dept(dept,head) 单独分出。"},{"type":"tip","text":"“X→Y，Y→Z”可推出 X→Z，但范式中的传递依赖判断还要看中间决定因素是否为超码，以及被依赖属性是否为主属性。"}],"tags":["规范化","重点"],"minutes":10},{"id":"closure-keys","module":"m5","title":"属性闭包与候选码求解","summary":"既要证明能决定全部属性，也要证明没有多余属性。","blocks":[{"type":"steps","title":"求 X⁺ 的方法","items":["把闭包初始化为 X。","若某依赖 A→B 的左侧 A 已包含于闭包，就把 B 加入。","重复直到不再增加。若 X⁺=U，则 X 是超码。","再检查最小性：删去任意一个属性后不再能决定 U，才是候选码。"]},{"type":"text","title":"例：R(A,B,C,D,E)","text":"设 F={A→D，B→C，E→A}。B 与 E 没出现在任何右侧，因此每个候选码都必须含 B、E。从 BE 出发，B→C 加入 C，E→A 加入 A，A→D 加入 D，所以 (BE)⁺=ABCDE。B⁺=BC，E⁺=EAD，均不覆盖全部属性，所以 BE 是候选码，也是唯一候选码。"},{"type":"text","title":"再看一个多候选码例子","text":"R(A,B,C)，F={A→B，B→A}。C 必须包含在码中；AC 与 BC 均能决定 ABC，且都最小，因此候选码为 AC、BC。主属性是 A、B、C，不是只选 AC 后就把 B 当非主属性。"},{"type":"tip","text":"“只出现在左侧”的属性是每个候选码必须包含的属性，但它们的集合不一定已经构成候选码。必须继续求闭包。"}],"tags":["规范化","候选码","重点"],"minutes":10},{"id":"normal-forms","module":"m5","title":"1NF、2NF、3NF 与 BCNF","summary":"用准确条件判断最高范式，写出违反原因。","blocks":[{"type":"table","title":"范式阶梯","heads":["范式","判定条件","常见问题"],"rows":[["1NF","属性值在选定模型下不可再分","一个单元格保存多门课程列表"],["2NF","1NF，且每个非主属性完全依赖每个候选码","复合码中的一部分已决定非主属性"],["3NF","对每个非平凡 X→A，X 是超码或 A 是主属性","非超码决定非主属性"],["BCNF","每个非平凡函数依赖的决定因素均为超码","主属性之间也可能违反"]]},{"type":"text","title":"从 2NF 到 3NF","text":"Student(sno,dept,head) 的码是 sno，没有非主属性对码的部分依赖，满足 2NF。但 dept→head 中 dept 不是超码，head 不是主属性，因此不满足 3NF。"},{"type":"text","title":"3NF 不等于 BCNF","text":"R(S,T,C)，F={SC→T，T→C}。候选码为 SC 与 ST，三个属性都是主属性。T→C 的右端 C 是主属性，所以符合 3NF；T 不是超码，所以违反 BCNF。"},{"type":"steps","title":"范式题的答题顺序","items":["列出业务假设与函数依赖。","求所有候选码，并区分主属性、非主属性。","从低到高检验，指出具体违反的函数依赖。","给出最高范式与分解方案，再检查连接和依赖。"]},{"type":"tip","text":"只说“一张表管一件事”不够。需要给出码、依赖和违反条件的证据。"}],"tags":["规范化","重点"],"minutes":10},{"id":"decomposition","module":"m5","title":"规范化分解与异常消除","summary":"把选课大表一步步拆到 3NF。","blocks":[{"type":"text","title":"初始模式与假设","text":"R(sno,sname,dept,head,cno,cname,grade)，F={sno→sname,dept；dept→head；cno→cname；(sno,cno)→grade}。码为 (sno,cno)。重复保存姓名、课程名、系主任会导致更新异常；没有学生时难以独立插入系信息；删除最后一名学生可能丢失系信息。"},{"type":"steps","title":"分解过程","items":["消除部分依赖：学生信息 S(sno,sname,dept,head)、课程 C(cno,cname)、选课 SC(sno,cno,grade)。","学生信息中仍有 sno→dept→head，分为 Student(sno,sname,dept) 与 Dept(dept,head)。","最终四个关系分别管理学生、系、课程与选课，按给定依赖均满足 3NF。"]},{"type":"text","title":"无损连接与依赖保持","text":"无损连接要求分解后的关系自然连接能恢复原关系，不产生伪元组。二元分解 R→R1,R2，在函数依赖条件下，若交集能决定 R1 或 R2，则是无损分解。依赖保持要求不必连接所有表，就能在各子模式上检查原有依赖。两者是不同要求。"},{"type":"text","title":"验证这个例子","text":"分出 Dept 时，共同属性 dept 决定 Dept 的全部属性，支持无损连接；sno→sname,dept、dept→head、cno→cname 与 (sno,cno)→grade 都可以在各自表中检查。"},{"type":"tip","text":"不能随机按字段个数拆表，也不能只证明每张表范式更高就宣称分解正确。"}],"tags":["规范化","综合题","重点"],"minutes":10},{"id":"plsql-block","module":"m6","title":"MySQL 程序块、变量与赋值","summary":"在存储过程的 BEGIN ... END 中声明变量、处理条件并输出结果。","blocks":[{"type":"code","title":"存储过程中的程序块","code":"DROP PROCEDURE IF EXISTS show_student;\nDELIMITER //\nCREATE PROCEDURE show_student(IN p_sno VARCHAR(8))\nBEGIN\nDECLARE v_name VARCHAR(40);\n  DECLARE v_found BOOLEAN DEFAULT TRUE;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_found = FALSE;\n  SELECT sname INTO v_name FROM Student WHERE sno = p_sno;\n  IF v_found THEN\n    SELECT v_name AS student_name;\n  ELSE\n    SELECT '学生不存在' AS message;\n  END IF;\nEND //\nDELIMITER ;\nCALL show_student('S01');","dialect":"MySQL 8.0.16+"},{"type":"text","title":"程序块与分隔符","text":"MySQL 将 DECLARE 写在 BEGIN ... END 的开头，先声明变量和条件，再声明游标，最后声明 HANDLER。局部变量用 SET v_name = ... 赋值，SELECT ... INTO 用于接收查询结果。DELIMITER 是 mysql 客户端切换语句结束符的命令，程序创建后用 CALL 调用。"},{"type":"table","title":"局部变量与会话变量","heads":["写法","使用范围"],"rows":[["DECLARE v_grade DECIMAL(5,2);","存储程序的局部变量，声明时明确类型"],["SET v_grade = 85;","程序块内赋值"],["SET @course_count = 0;","当前连接的会话变量，可在 CALL 中接收 OUT 参数"]]},{"type":"tip","text":"MySQL 不支持直接执行独立匿名 DECLARE 程序块。复制示例时连同 CREATE PROCEDURE、DELIMITER 与 CALL 一起执行；变量类型应与相关列匹配。"}],"tags":["MySQL 编程","重点"],"minutes":10},{"id":"select-into","module":"m6","title":"SELECT INTO 与条件处理","summary":"接收单行结果，并区分零行、多行和业务错误。","blocks":[{"type":"code","title":"接收单行结果","code":"DROP PROCEDURE IF EXISTS find_student;\nDELIMITER //\nCREATE PROCEDURE find_student(IN p_sno VARCHAR(8))\nBEGIN\nDECLARE v_name VARCHAR(40);\n  DECLARE v_age INT;\n  DECLARE v_found BOOLEAN DEFAULT TRUE;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_found = FALSE;\n  DECLARE EXIT HANDLER FOR 1172\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '查询返回多行';\n  SELECT sname, age INTO v_name, v_age FROM Student WHERE sno = p_sno;\n  IF v_found THEN\n    SELECT v_name AS student_name, v_age AS age;\n  ELSE\n    SELECT '无此学生' AS message;\n  END IF;\nEND //\nDELIMITER ;\nCALL find_student('S01');","dialect":"MySQL 8.0.16+"},{"type":"text","title":"零行和多行行为","text":"SELECT ... INTO 按位置把列值写入变量，列数和变量数需一致。零行会产生 1329（No data）条件，变量值保持原样，可用 NOT FOUND 处理器捕获。多行会产生 1172 错误。不能用随意加 LIMIT 1 掩盖本应唯一的业务条件。"},{"type":"text","title":"聚合查询的边界","text":"不带 GROUP BY 的 SELECT COUNT(*) INTO v_n 即使没有匹配行，也返回一行 0；AVG 返回一行 NULL。带 GROUP BY 且无任何分组时，仍可能返回零行。"},{"type":"code","title":"用 SIGNAL 抛出业务错误","code":"DROP PROCEDURE IF EXISTS validate_grade;\nDELIMITER //\nCREATE PROCEDURE validate_grade(IN p_grade DECIMAL(5,2))\nBEGIN\nIF p_grade IS NULL OR p_grade \u003c 0 OR p_grade > 100 THEN\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '成绩必须非空且在 0 到 100 之间';\n  END IF;\n  SELECT '成绩有效' AS message;\nEND //\nDELIMITER ;\nCALL validate_grade(85);","dialect":"MySQL 8.0.16+"},{"type":"tip","text":"CONTINUE HANDLER 处理后继续程序，EXIT HANDLER 退出它所在的 BEGIN ... END 块。需要把错误传给调用者时可用 RESIGNAL，避免静默吞掉错误。"}],"tags":["MySQL 编程","异常","重点"],"minutes":10},{"id":"control-flow","module":"m6","title":"分支与 LOOP / WHILE / REPEAT","summary":"用 ELSEIF、LEAVE 与循环条件控制存储程序。","blocks":[{"type":"code","title":"成绩分段","code":"DROP PROCEDURE IF EXISTS classify_grade;\nDELIMITER //\nCREATE PROCEDURE classify_grade(IN p_grade DECIMAL(5,2))\nBEGIN\nDECLARE v_label VARCHAR(10);\n  IF p_grade IS NULL THEN SET v_label = '未出分';\n  ELSEIF p_grade >= 90 THEN SET v_label = '优秀';\n  ELSEIF p_grade >= 60 THEN SET v_label = '及格';\n  ELSE SET v_label = '不及格';\n  END IF;\n  SELECT v_label AS grade_label;\nEND //\nDELIMITER ;\nCALL classify_grade(92);","dialect":"MySQL 8.0.16+"},{"type":"code","title":"三种循环的完整示例","code":"DROP PROCEDURE IF EXISTS loop_demo;\nDELIMITER //\nCREATE PROCEDURE loop_demo()\nBEGIN\nDECLARE v_i INT DEFAULT 0;\n  count_loop: LOOP\n    SET v_i = v_i + 1;\n    IF v_i >= 10 THEN LEAVE count_loop; END IF;\n  END LOOP count_loop;\n  SELECT v_i AS loop_result;\n  SET v_i = 0;\n  WHILE v_i \u003c 10 DO\n    SET v_i = v_i + 1;\n  END WHILE;\n  SELECT v_i AS while_result;\n  SET v_i = 0;\n  REPEAT\n    SET v_i = v_i + 1;\n  UNTIL v_i >= 10 END REPEAT;\n  SELECT v_i AS repeat_result;\nEND //\nDELIMITER ;\nCALL loop_demo();","dialect":"MySQL 8.0.16+"},{"type":"text","title":"循环的边界","text":"LOOP 通过带标签的 LEAVE 退出；WHILE 在每轮开始前判断条件；REPEAT 先执行一次，再检查 UNTIL 的结束条件。每种循环都应明确初值、每轮进展和终止条件。"},{"type":"tip","text":"MySQL 没有数值 FOR i IN 1..10 循环，也没有游标 FOR 自动遍历。用 WHILE 或 LOOP 表达计数和遍历。"}],"tags":["MySQL 编程","控制流"],"minutes":10},{"id":"cursor","module":"m6","title":"MySQL 游标与结束条件","summary":"用游标、FETCH 和 NOT FOUND 处理器逐行处理查询结果。","blocks":[{"type":"code","title":"游标的完整生命周期","code":"DROP PROCEDURE IF EXISTS print_course_scores;\nDELIMITER //\nCREATE PROCEDURE print_course_scores(IN p_cno VARCHAR(4))\nBEGIN\nDECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_sno VARCHAR(8);\n  DECLARE v_grade DECIMAL(5,2);\n  DECLARE c_scores CURSOR FOR\n    SELECT sno, grade FROM SC WHERE cno = p_cno ORDER BY sno;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n  OPEN c_scores;\n  read_loop: LOOP\n    FETCH c_scores INTO v_sno, v_grade;\n    IF done THEN LEAVE read_loop; END IF;\n    SELECT v_sno AS sno, v_grade AS grade;\n  END LOOP read_loop;\n  CLOSE c_scores;\nEND //\nDELIMITER ;\nCALL print_course_scores('C01');","dialect":"MySQL 8.0.16+"},{"type":"table","title":"四个步骤","heads":["步骤","语句或作用"],"rows":[["声明","DECLARE c_scores CURSOR FOR SELECT ..."],["打开","OPEN c_scores;"],["提取","FETCH c_scores INTO v_sno, v_grade;"],["关闭","CLOSE c_scores;"]]},{"type":"text","title":"输入参数与游标查询","text":"示例的 p_cno 是存储过程输入参数，游标查询可以直接引用它。游标本身不定义参数。FETCH 的接收变量逐列声明，类型和数量应与 SELECT 列匹配。MySQL 游标只读，向前提取，不通过游标直接更新记录。"},{"type":"text","title":"为什么先 FETCH 再检查 done","text":"最后一次 FETCH 找不到行时，NOT FOUND 处理器将 done 设为 TRUE；立即 LEAVE，不能继续处理接收变量中的旧值。完成后显式 CLOSE。"},{"type":"tip","text":"声明顺序是变量／条件、游标、HANDLER。能用一条 UPDATE 统一完成的修改，通常优先集合式 SQL；逐行输出或不同处理才使用游标。"}],"tags":["MySQL 编程","游标","重点"],"minutes":10},{"id":"procedure","module":"m6","title":"存储过程与 IN / OUT 参数","summary":"把可复用的业务操作封装成命名程序。","blocks":[{"type":"code","title":"通过 OUT 参数返回数量","code":"DROP PROCEDURE IF EXISTS get_course_count;\nDELIMITER //\nCREATE PROCEDURE get_course_count(IN p_sno VARCHAR(8), OUT p_count INT)\nBEGIN\nSELECT COUNT(*) INTO p_count FROM SC WHERE sno = p_sno;\nEND //\nDELIMITER ;\nCALL get_course_count('S01', @course_count);\nSELECT @course_count AS course_count;","dialect":"MySQL 8.0.16+"},{"type":"table","title":"参数模式","heads":["模式","用途"],"rows":[["IN","输入，可在过程内读取"],["OUT","向调用者输出结果"],["INOUT","既接收初值，又带回修改结果"]]},{"type":"text","title":"定义、调用与提前退出","text":"CREATE PROCEDURE 保存定义，CALL 才执行过程。参数模式写在参数名前面。OUT 参数可由会话变量 @course_count 接收；在另一个过程中也可用局部变量接收。需要提前退出过程时，给最外层程序块加标签，并用 LEAVE 标签名。"},{"type":"tip","text":"MySQL 不支持 CREATE OR REPLACE PROCEDURE。需要重建时先 DROP PROCEDURE IF EXISTS，再 CREATE PROCEDURE。过程可返回结果集或 OUT 参数；RETURN 表达式属于函数。"}],"tags":["MySQL 编程","存储过程","重点"],"minutes":10},{"id":"function","module":"m6","title":"存储函数与返回值","summary":"让计算结果成为表达式的一部分。","blocks":[{"type":"code","title":"返回课程平均成绩","code":"DROP FUNCTION IF EXISTS course_average;\nDELIMITER //\nCREATE FUNCTION course_average(p_cno VARCHAR(4))\nRETURNS DECIMAL(6,2) READS SQL DATA\nBEGIN\nDECLARE v_avg DECIMAL(6,2);\n  SELECT AVG(grade) INTO v_avg FROM SC WHERE cno = p_cno;\n  RETURN v_avg;\nEND //\nDELIMITER ;\nSELECT course_average('C01') AS avg_grade;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"平均分与空值","text":"AVG(grade) 只统计非空成绩；用 SUM(grade)/COUNT(*) 会把未出分记录算进分母。没有任何已出分记录时返回 NULL；若业务明确要求返回 0，可用 COALESCE(v_avg,0)。"},{"type":"table","title":"过程与函数","heads":["比较","过程","函数"],"rows":[["定义","PROCEDURE","FUNCTION ... RETURNS 类型"],["结果","结果集、OUT / INOUT 参数","RETURN 表达式"],["调用","CALL 名称(...)","SELECT 名称(...)"],["参数模式","IN / OUT / INOUT","输入参数，不写模式关键字"]]},{"type":"tip","text":"函数的正常执行路径都应返回值。读取表的函数可声明 READS SQL DATA；不要把依赖表中数据的函数错误标为 DETERMINISTIC。函数不能直接返回普通多行 SELECT 结果集。"}],"tags":["MySQL 编程","存储函数","重点"],"minutes":10},{"id":"trigger","module":"m6","title":"MySQL 触发器、OLD / NEW 与审计","summary":"在数据事件发生时记录真实变化，正确处理 NULL。","blocks":[{"type":"code","title":"记录成绩变化","code":"CREATE TABLE GradeAudit (\n  sno VARCHAR(8), cno VARCHAR(4),\n  old_grade DECIMAL(5,2), new_grade DECIMAL(5,2), changed_at DATETIME\n);\nDELIMITER //\nCREATE TRIGGER trg_grade_audit\nAFTER UPDATE ON SC\nFOR EACH ROW\nBEGIN\n  IF NOT (OLD.grade \u003c=> NEW.grade) THEN\n    INSERT INTO GradeAudit(sno,cno,old_grade,new_grade,changed_at)\n    VALUES(OLD.sno,OLD.cno,OLD.grade,NEW.grade,NOW());\n  END IF;\nEND //\nDELIMITER ;","dialect":"MySQL 8.0.16+"},{"type":"text","title":"时机、事件与粒度","text":"MySQL 的表触发器使用 BEFORE 或 AFTER，事件为 INSERT、UPDATE、DELETE 之一，必须写 FOR EACH ROW。UPDATE 中 OLD.grade 是修改前，NEW.grade 是修改后，不加冒号。INSERT 使用 NEW，DELETE 使用 OLD。触发器由事件自动执行。"},{"type":"text","title":"只记录真实变化","text":"\u003c=> 是 NULL 安全相等运算。NOT (OLD.grade \u003c=> NEW.grade) 同时覆盖普通值变化、NULL 变为成绩、成绩变为 NULL，并跳过值未变化的 UPDATE。MySQL 没有 UPDATE OF grade 事件限定，需在触发器体中比较。"},{"type":"text","title":"触发器限制与事务","text":"触发器不能直接返回结果集，不能执行 COMMIT、ROLLBACK 或开启新事务，也不能修改触发语句已经使用的表。审计写入其他 InnoDB 表时，与原修改属于同一事务；原事务回滚时，审计也回滚。"},{"type":"tip","text":"若需调整即将写入的列值，可在 BEFORE 触发器中 SET NEW.列名 = ...。不要在 SC 的触发器里再次 UPDATE SC。"}],"tags":["MySQL 编程","触发器","易错"],"minutes":10},{"id":"design-process","module":"m7","title":"数据库设计的六个阶段","summary":"从需求到实现，明确每一阶段的产出。","blocks":[{"type":"steps","title":"数据库设计过程","items":["需求分析：调查数据、处理、安全与完整性要求，形成需求说明、数据字典和数据流图。","概念结构设计：抽象实体、属性和联系，形成独立于 DBMS 的 E-R 模型。","逻辑结构设计：转为关系模式，确定码与约束，进行规范化。","物理结构设计：结合 DBMS、负载和硬件选择存储与索引。","数据库实施：编写建库建表脚本、装载数据、调试并试运行。","运行与维护：监控、备份恢复、调整性能并随需求演化。"]},{"type":"text","title":"数据字典与数据流图","text":"数据字典描述数据的含义、类型、取值范围等元数据；数据流图表达数据如何在处理过程间流动。二者不是表中业务数据的简单列表。"},{"type":"table","title":"局部 E-R 图集成冲突","heads":["冲突","例子","处理思路"],"rows":[["命名冲突","同名异义、同义异名","统一术语与命名"],["属性冲突","年龄分别用整数和出生日期表达","统一语义、类型、范围"],["结构冲突","同一对象一处是实体一处是属性","根据业务目标统一抽象"]]},{"type":"tip","text":"考试给出一个管理系统需求时，先把业务限制写清，再画图。不要直接从想象的字段列表开始。"}],"tags":["设计","综合题","重点"],"minutes":10},{"id":"er-conversion","module":"m7","title":"E-R 图转换为关系模式","summary":"把 1:1、1:n 与 m:n 正确映射成表。","blocks":[{"type":"table","title":"转换规则","heads":["联系类型","常用转换","注意"],"rows":[["实体型","每个实体型对应一个关系","实体码作为候选主码"],["1:1","可独立成表，或将外键及联系属性并入一端","需 UNIQUE 等约束表达一对一"],["1:n","把 1 端码作为外键放在 n 端，带上联系属性","不要在 1 端保存多个 n 端编号"],["m:n","建立独立联系表，含两端码和联系属性","两端码组合通常为候选码，取决于业务"]]},{"type":"text","title":"学生选课的转换","text":"学生 Student(sno,sname,dept)、课程 Course(cno,cname,credit)、选课 SC(sno,cno,grade)。SC 的主码为 (sno,cno)，sno 和 cno 各自引用实体表。如果题目要求同一课程按学期重修，需要扩充联系的标识。"},{"type":"text","title":"一个关系可以身兼多职","text":"教师 Teach(tno,tname,cno) 中，若每位教师只教一门课，一门课可由多位教师教授，则教师是 n 端，cno 放在教师表。若教师与课程变为多对多，则另建 Teaching(tno,cno,...)。"},{"type":"tip","text":"给出关系模式时同时标明 PK、FK 和引用目标；只列字段而不标码，设计答案不完整。"}],"tags":["设计","E-R","重点"],"minutes":10},{"id":"exam-method","module":"m7","title":"综合题作答与复查方法","summary":"用一条业务线串起设计、建表、查询和编程。","blocks":[{"type":"steps","title":"综合题的作答顺序","items":["圈定实体、标识属性、联系基数及特殊业务规则。","画 E-R 图，标出联系属性，再转换为关系模式。","列函数依赖、候选码、最高范式及必要分解。","按被引用表在前、引用表在后的顺序建表。","写查询：连接、筛选、分组、并列与 NULL 边界逐项核对。","写 MySQL 存储程序：参数模式、变量类型、声明顺序、HANDLER、游标关闭、RETURN 与事务边界逐项核对。"]},{"type":"table","title":"交卷前的核对","heads":["题型","必须检查"],"rows":[["设计","m:n 是否成独立表；1:n 外键是否在 n 端"],["范式","所有候选码、主属性、违反依赖与分解理由"],["SQL","连接条件、WHERE/HAVING、NULL、去重、并列"],["游标","FETCH 后再判断退出；使用后关闭"],["过程／函数","IN/OUT/INOUT、DECLARE、CALL、RETURNS/RETURN、HANDLER"],["触发器","BEFORE/AFTER、FOR EACH ROW、OLD/NEW、NULL 安全比较、事务限制"]]},{"type":"text","title":"怎样使用这个网站复习","text":"第一次学习按章节打底；第二轮进入 SQL 实验室实际运行查询；最后在综合训练里先独立写答案，再展开参考与评分要点。自测题用于查漏补缺，综合训练贴近闭卷综合题的任务结构。"}],"tags":["考试","综合题","重点"],"minutes":10}],"quiz":[{"id":"q01","module":"m1","question":"负责定义、查询和管理数据库的软件是？","options":["DB","DBMS","DBS","数据字典"],"answer":1,"explanation":"DB 是数据集合，DBMS 是数据库管理软件，DBS 是完整的数据库系统。"},{"id":"q02","module":"m1","question":"模式／内模式映像主要支持哪种独立性？","options":["逻辑独立性","物理独立性","事务独立性","用户独立性"],"answer":1,"explanation":"内模式描述物理存储；改变存储安排后调整模式／内模式映像，逻辑结构可保持稳定。"},{"id":"q03","module":"m1","question":"数据模型的三个组成部分是？","options":["表、行、列","实体、属性、联系","数据结构、数据操作、完整性约束","模式、视图、用户"],"answer":2,"explanation":"实体、属性、联系是概念模型中的基本元素；数据模型更一般的组成是结构、操作和约束。"},{"id":"q04","module":"m1","question":"一个部门有多个职工，每个职工只属于一个部门，这是？","options":["1:1","1:n","m:n","无法判断"],"answer":1,"explanation":"从部门到职工是一对多，从职工到部门是多对一。"},{"id":"q05","module":"m2","question":"候选码与超码的关键差别在于？","options":["候选码只能有一列","候选码允许重复","候选码不含多余属性","超码必须是外键"],"answer":2,"explanation":"候选码是最小超码；它可以由多个属性组成。"},{"id":"q06","module":"m2","question":"R 有 3 行 2 列，S 有 4 行 3 列。R×S 有？","options":["7 行 5 列","12 行 6 列","12 行 5 列","7 行 6 列"],"answer":2,"explanation":"笛卡尔积的行数相乘，列数相加。"},{"id":"q07","module":"m2","question":"理论关系代数中，投影操作会？","options":["只选择行","选择列并去除重复元组","保留所有重复行","自动排序"],"answer":1,"explanation":"π 选择属性列，关系结果按集合语义去重；SQL 需 SELECT DISTINCT 对应。"},{"id":"q08","module":"m2","question":"自然连接会在什么属性上比较相等？","options":["任意一个属性","主键属性","全部同名属性","第一列"],"answer":2,"explanation":"自然连接在全部同名属性上做等值匹配，并合并同名列。"},{"id":"q09","module":"m2","question":"查询“选了所有必修课的学生”最直接对应哪种关系代数运算？","options":["并","差","除","笛卡尔积"],"answer":2,"explanation":"除法用于表示覆盖全部指定 Y 的 X。"},{"id":"q10","module":"m2","question":"SC 的主键为 (sno,cno)，sno 和 cno 分别引用学生和课程。哪项正确？","options":["主键不能包含外键","sno 和 cno 分别是外键","sno 单独必然是候选码","cno 必须唯一"],"answer":1,"explanation":"复合主键的组成列可以各自是外键；单独 sno 或 cno 不一定唯一。"},{"id":"q11","module":"m4","question":"要查询未出分记录，正确条件为？","options":["grade = NULL","grade \u003c> NULL","grade IS NULL","grade = 0"],"answer":2,"explanation":"与 NULL 的普通比较是 UNKNOWN，查询缺失值用 IS NULL。"},{"id":"q12","module":"m4","question":"SC 的 grade 值为 80、NULL、100。COUNT(grade) 和 AVG(grade) 是？","options":["3 和 60","2 和 90","3 和 90","2 和 60"],"answer":1,"explanation":"COUNT(grade) 和 AVG(grade) 都忽略 NULL，平均为 (80+100)/2。"},{"id":"q13","module":"m4","question":"按课程筛选“平均成绩至少 80”的组，应使用？","options":["WHERE AVG(grade)>=80","HAVING AVG(grade)>=80","ORDER BY grade>=80","WHERE COUNT(*)>=80"],"answer":1,"explanation":"聚合条件用于筛选组，应写 HAVING；WHERE 在分组前筛选行。"},{"id":"q14","module":"m4","question":"保留全部学生及其选课记录，包括未选课学生，应使用？","options":["Student INNER JOIN SC","Student LEFT JOIN SC","SC LEFT JOIN Student","CROSS JOIN"],"answer":1,"explanation":"左外连接保留左表所有行，右表没有匹配时补 NULL。"},{"id":"q15","module":"m4","question":"LEFT JOIN 后统计真实选课数，按学生分组，应优先使用？","options":["COUNT(*)","COUNT(sc.cno)","SUM(s.sno)","AVG(*)"],"answer":1,"explanation":"COUNT(*) 会计入空补齐的行；sc.cno 非空才代表有真实选课记录。"},{"id":"q16","module":"m4","question":"同一课程有两名学生并列最高分，使用 grade=(SELECT MAX(...)) 会？","options":["仅返回第一名","返回两名","报错","随机返回一名"],"answer":1,"explanation":"与最大值相等的所有行都会保留，适合未指定并列规则的最高分题。"},{"id":"q17","module":"m4","question":"标准 LIKE 中匹配任意一个字符的通配符是？","options":["%","_","*","[0-9]"],"answer":1,"explanation":"下划线匹配一个字符，百分号匹配任意长度字符串。"},{"id":"q18","module":"m4","question":"CHECK(grade BETWEEN 0 AND 100) 是否能独自拒绝 NULL？","options":["能","不能，还需要 NOT NULL","只有主键列不能","取决于 ORDER BY"],"answer":1,"explanation":"CHECK 接受 TRUE 或 UNKNOWN。NULL 产生 UNKNOWN，若要求有值需 NOT NULL。"},{"id":"q19","module":"m4","question":"UNION 与 UNION ALL 的主要差别是？","options":["UNION ALL 自动排序","UNION 去重，UNION ALL 保留重复","UNION 只能连接表","两者没有区别"],"answer":1,"explanation":"集合并采用去重语义，UNION ALL 则保留各查询结果中的重复。"},{"id":"q20","module":"m4","question":"删除一个普通视图会？","options":["删除其基表","删除视图定义，保留基表","清空基表数据","删除基表索引"],"answer":1,"explanation":"普通视图是虚拟表，删除视图不删除基表。"},{"id":"q21","module":"m4","question":"WITH CHECK OPTION 的作用是？","options":["允许任意视图更新","保证通过视图写入的数据满足视图条件","创建索引","加速聚合"],"answer":1,"explanation":"它约束可更新视图中的写入结果仍满足视图的过滤条件。"},{"id":"q22","module":"m4","question":"索引可能产生的代价是？","options":["增加写入维护与存储开销","让主键可重复","自动删除 NULL","取消外键"],"answer":0,"explanation":"索引有空间和维护成本，不能无条件为每个字段建立。"},{"id":"q23","module":"m5","question":"R(A,B,C)，F={A→B}。哪一项是候选码？","options":["A","B","AC","ABC"],"answer":2,"explanation":"C 不可由其他属性推出，AC 的闭包为 ABC；A 或 C 单独均不足，ABC 含多余 B。"},{"id":"q24","module":"m5","question":"若候选码为 AB，且 A→C，C 为非主属性，则 C 对 AB 是？","options":["完全依赖","部分依赖","无依赖","多值依赖"],"answer":1,"explanation":"AB 的真子集 A 已能决定 C，所以 C 部分依赖于 AB。"},{"id":"q25","module":"m5","question":"候选码为 sno，存在 sno→dept、dept→head。head 是非主属性，该模式至少可能违反？","options":["1NF","2NF 的部分依赖要求","3NF","实体完整性"],"answer":2,"explanation":"dept 非超码且决定非主属性 head，形成对 sno 的传递依赖；这是 3NF 问题。"},{"id":"q26","module":"m5","question":"主属性指？","options":["只出现在选定主键中的属性","属于任一候选码的属性","所有有索引的属性","所有非空属性"],"answer":1,"explanation":"主属性要看全部候选码的并集，不能只看某个主码。"},{"id":"q27","module":"m5","question":"BCNF 对每个非平凡函数依赖 X→Y 要求？","options":["Y 必为主属性","X 必为超码","X 必为单属性","Y 必为外键"],"answer":1,"explanation":"BCNF 要求每个非平凡依赖的决定因素为超码，比 3NF 更严格。"},{"id":"q28","module":"m5","question":"只在依赖左侧出现、从未出现在右侧的属性一定？","options":["单独就是候选码","必须包含于每个候选码","是非主属性","可以删除"],"answer":1,"explanation":"它无法从其他属性推出，所以任何候选码必须含它，但还需闭包检查是否足够。"},{"id":"q29","module":"m5","question":"无损连接最关心什么？","options":["表数更少","连接后能恢复原关系且不产生伪元组","列名更短","查询一定更快"],"answer":1,"explanation":"无损性是信息保持要求，和性能、依赖保持是不同问题。"},{"id":"q30","module":"m6","question":"在 MySQL 存储过程中，把局部变量 v_i 设为 1 的正确语句是？","options":["v_i = 1;","v_i := 1;","SET v_i = 1;","v_i => 1;"],"answer":2,"explanation":"MySQL 局部变量使用 SET 赋值，也可以通过 SELECT ... INTO 接收查询结果。"},{"id":"q31","module":"m6","question":"MySQL 的 SELECT ... INTO 查询返回零行时，默认行为是？","options":["变量自动为零","产生 1329 条件，变量值保持原样","产生 1172 多行错误","自动插入一行"],"answer":1,"explanation":"零行产生 No data 条件，可用 NOT FOUND HANDLER 处理；变量不会自动清零。"},{"id":"q32","module":"m6","question":"SELECT COUNT(*) INTO v_n FROM SC WHERE 1=0 会？","options":["产生 NOT FOUND 条件","v_n 为 NULL","v_n 为 0","产生 1172 错误"],"answer":2,"explanation":"不带 GROUP BY 的聚合查询仍有一行结果，COUNT 返回 0。"},{"id":"q33","module":"m6","question":"显式游标循环中，正确的次序是？","options":["输出→FETCH→退出判断","FETCH→退出判断→处理记录","退出判断→CLOSE→FETCH","OPEN→CLOSE→输出"],"answer":1,"explanation":"先提取再判断是否成功，失败后立即退出，避免重复或无效处理。"},{"id":"q34","module":"m6","question":"MySQL 游标 FETCH 到末尾时，常用什么方式结束循环？","options":["游标自动关闭","CONTINUE HANDLER FOR NOT FOUND 设置 done，再 LEAVE","自动执行 COMMIT","直接继续使用上次变量值"],"answer":1,"explanation":"先声明 NOT FOUND 处理器，FETCH 后检查 done，退出循环后显式 CLOSE。"},{"id":"q35","module":"m6","question":"MySQL 在存储过程中声明一个成绩局部变量，正确的是？","options":["DECLARE v_grade DECIMAL(5,2);","DECLARE v_grade LIKE SC.grade;","v_grade SC.grade;","VAR v_grade;"],"answer":0,"explanation":"DECLARE 位于 BEGIN ... END 的开头，类型显式写为 DECIMAL(5,2) 等。"},{"id":"q36","module":"m6","question":"MySQL 过程需要向调用者输出数量，适合使用哪种参数？","options":["IN","OUT","PRIVATE","RETURNS 参数"],"answer":1,"explanation":"OUT 参数写在参数名之前，调用时可用 @变量接收。"},{"id":"q37","module":"m6","question":"MySQL 存储函数必须具备什么？","options":["手工 OPEN 游标","RETURNS 类型和正常路径的 RETURN 值","COMMIT","OUT 参数"],"answer":1,"explanation":"函数定义使用 RETURNS 指定返回类型，函数体用 RETURN 表达式返回值。"},{"id":"q38","module":"m6","question":"MySQL 行级 UPDATE 触发器中，修改前的成绩写为？","options":["NEW.grade","OLD.grade","BEFORE.grade","OLD(grade)"],"answer":1,"explanation":"OLD.grade 表示修改前的值，NEW.grade 表示修改后的值。"},{"id":"q39","module":"m6","question":"MySQL 触发器中的哪种操作受到禁止？","options":["向独立审计表插入记录","修改触发语句已经使用的原表","比较 OLD 与 NEW","用 NOW() 记录时间"],"answer":1,"explanation":"触发器不能再次修改触发语句已使用的表，也不能执行 COMMIT 或 ROLLBACK。"},{"id":"q40","module":"m7","question":"学生与课程为 m:n，成绩属于选修联系，常见转换是？","options":["把全部课程号塞进学生表一列","建立 SC(sno,cno,grade)","把学生姓名当课程主键","删除联系属性"],"answer":1,"explanation":"多对多联系独立成表，带上两端实体码和联系属性。"},{"id":"q41","module":"m7","question":"从 E-R 模型转换到关系模式属于？","options":["需求分析","概念设计","逻辑结构设计","运行维护"],"answer":2,"explanation":"概念设计产生 E-R 模型；逻辑设计把它转换为关系模式并规范化。"},{"id":"q42","module":"m7","question":"部门与职工为 1:n，通常把哪个外键放到哪张表？","options":["职工号放部门表","部门号放职工表","两表均无外键","两个编号都放姓名列"],"answer":1,"explanation":"一端的码放在多端，才能让每个职工指向所属部门。"}],"labs":[{"id":"lab1","title":"01 · 单表筛选","goal":"查询计算机系且年龄小于 21 岁的学生，输出 sno、sname、age。","starter":"SELECT sno, sname, age\nFROM Student\nWHERE -- 补全条件\n;","answer":"SELECT sno,sname,age FROM Student WHERE dept='计算机' AND age\u003c21;","hint":"用 AND 同时表达系别和年龄。","order":false},{"id":"lab2","title":"02 · 三表连接","goal":"查询所有已有选课记录的学生姓名、课程名、成绩，输出 sname、cname、grade。","starter":"SELECT s.sname, c.cname, sc.grade\nFROM Student s\n-- 补全连接\n;","answer":"SELECT s.sname,c.cname,sc.grade FROM Student s JOIN SC sc ON sc.sno=s.sno JOIN Course c ON c.cno=sc.cno;","hint":"用 SC 把 Student 与 Course 连接起来，未出分的选课仍应保留。","order":false},{"id":"lab3","title":"03 · 分组与 HAVING","goal":"查询已出分人数至少为 2 的课程，输出 cno、graded_count（非空成绩人数）。","starter":"SELECT cno, COUNT(grade) AS graded_count\nFROM SC\n-- 补充分组与组条件\n;","answer":"SELECT cno,COUNT(grade) AS graded_count FROM SC GROUP BY cno HAVING COUNT(grade)>=2;","hint":"COUNT(grade) 忽略 NULL，分组筛选写 HAVING。","order":false},{"id":"lab4","title":"04 · 并列最高分","goal":"查询数据库原理（C01）的所有最高分学生，输出 sno、grade。","starter":"SELECT sno, grade FROM SC\nWHERE cno = 'C01'\n-- 补全最高分条件\n;","answer":"SELECT sno,grade FROM SC WHERE cno='C01' AND grade=(SELECT MAX(grade) FROM SC WHERE cno='C01');","hint":"用等于 MAX 的子查询，保留并列。","order":false},{"id":"lab5","title":"05 · 没有选课的学生","goal":"查询一门课也没选的学生，输出 sno、sname。","starter":"SELECT s.sno, s.sname FROM Student s\nWHERE -- 补全无匹配条件\n;","answer":"SELECT s.sno,s.sname FROM Student s WHERE NOT EXISTS(SELECT 1 FROM SC sc WHERE sc.sno=s.sno);","hint":"相关子查询可判断该学生是否存在任何选课记录。","order":false},{"id":"lab6","title":"06 · 选修全部课程","goal":"查询选齐 Course 中全部课程的学生，输出 sno、sname。","starter":"SELECT s.sno, s.sname FROM Student s\nWHERE NOT EXISTS (\n  -- 查找该学生未选的课程\n);","answer":"SELECT s.sno,s.sname FROM Student s WHERE NOT EXISTS(SELECT 1 FROM Course c WHERE NOT EXISTS(SELECT 1 FROM SC sc WHERE sc.sno=s.sno AND sc.cno=c.cno));","hint":"不存在一门课程，使该学生没有对应选课记录。","order":false},{"id":"lab7","title":"07 · 左连接与空值","goal":"查询所有学生及其 C01 成绩，输出 sno、sname、grade，未选 C01 的学生也必须出现。","starter":"SELECT s.sno, s.sname, sc.grade\nFROM Student s\n-- 补全左连接\n;","answer":"SELECT s.sno,s.sname,sc.grade FROM Student s LEFT JOIN SC sc ON sc.sno=s.sno AND sc.cno='C01';","hint":"课程条件写在 ON，避免 WHERE 排除空补齐行。","order":false},{"id":"lab8","title":"08 · 高于本课程均分","goal":"查询成绩高于所选课程平均分的选课记录，输出 sno、cno、grade。","starter":"SELECT sc.sno, sc.cno, sc.grade\nFROM SC sc\nWHERE sc.grade > (\n  -- 该课程的平均分\n);","answer":"SELECT sc.sno,sc.cno,sc.grade FROM SC sc WHERE sc.grade>(SELECT AVG(t.grade) FROM SC t WHERE t.cno=sc.cno);","hint":"子查询用课程号与外层关联，AVG 忽略 NULL。","order":false},{"id":"lab9","title":"09 · 学分汇总","goal":"查询所有学生已经获得的总学分，60 分及以上获得课程学分，未获得学分的学生计 0。输出 sno、earned_credit。","starter":"SELECT s.sno,\n  -- 汇总及格课程的学分\nFROM Student s\n;","answer":"SELECT s.sno,COALESCE(SUM(CASE WHEN sc.grade>=60 THEN c.credit ELSE 0 END),0) AS earned_credit FROM Student s LEFT JOIN SC sc ON sc.sno=s.sno LEFT JOIN Course c ON c.cno=sc.cno GROUP BY s.sno;","hint":"用 LEFT JOIN 保留全部学生，用 CASE 区分及格与未及格。","order":false},{"id":"lab10","title":"10 · 多字段排序","goal":"查询已出分的 C01 成绩，输出 sno、grade，按成绩降序，再按学号升序。","starter":"SELECT sno, grade FROM SC\nWHERE cno = 'C01' AND grade IS NOT NULL\n-- 补全排序\n;","answer":"SELECT sno,grade FROM SC WHERE cno='C01' AND grade IS NOT NULL ORDER BY grade DESC,sno ASC;","hint":"ORDER BY grade DESC, sno ASC。","order":true}],"cases":[{"id":"course-case","title":"学生选课管理系统","label":"核心综合题","summary":"从 E-R 设计到查询、游标、存储过程与函数，串起一整道管理系统综合题。","minutes":65,"requirement":"一个学生只属于一个系，一个系有多名学生且有一位系主任。学生可以选多门课，课程可以被多名学生选修。每名学生对每门课最多有一条选课记录，成绩可为空，成绩范围为 0～100。课程有课程号、名称、学分；只有成绩达到 60 分才获得学分。","entities":[["Dept","dept · PK","head"],["Student","sno · PK","sname / dept · FK / age"],["SC","sno + cno · PK","两列均为 FK / grade"],["Course","cno · PK","cname / credit"]],"relations":"Dept 1 → n Student；Student 1 → n SC；Course 1 → n SC。","tasks":[{"title":"1. 设计 E-R 图并转成关系模式","prompt":"写出实体、联系及其基数，再标注每张表的主键、外键。","answer":"系与学生为 1:n；学生与课程为 m:n，成绩是选修联系的属性。转换为 Dept(dept,head)、Student(sno,sname,dept,age)、Course(cno,cname,credit)、SC(sno,cno,grade)。Student.dept 引用 Dept.dept；SC 的两列分别引用学生、课程。","checks":["实体及标识属性完整","明确两个方向的基数","m:n 转为独立联系表，成绩放 SC","复合主键及外键引用准确"],"code":""},{"title":"2. 函数依赖与规范化","prompt":"若原始大表为 R(sno,sname,age,dept,head,cno,cname,credit,grade)，列出主要依赖并说明如何达到 3NF。","answer":"sno→sname,age,dept；dept→head；cno→cname,credit；(sno,cno)→grade。候选码为 (sno,cno)。姓名、年龄、系、课程名、学分存在对复合码的部分依赖；系主任还存在通过 dept 的传递依赖。分解为上述四张表，消除这些依赖。按给定依赖，各表均满足 3NF。","checks":["给出候选码及最小性","指出具体部分依赖","指出 sno→dept→head","分解后说明码、依赖与无损性"],"code":""},{"title":"3. 写建表语句","prompt":"使用 MySQL 语法建立四张表，设置主键、外键、非空和成绩范围。","answer":"先建被引用的 Dept、Course，再建 Student 和 SC。NULL 表示未出分，CHECK 并不拒绝 NULL。","checks":["父表先建","SC 复合主键","所有引用目标正确","成绩 CHECK 与 NULL 语义正确"],"code":"CREATE TABLE Dept (\n  dept VARCHAR(30) PRIMARY KEY, head VARCHAR(40) NOT NULL\n);\nCREATE TABLE Student (\n  sno VARCHAR(8) PRIMARY KEY, sname VARCHAR(40) NOT NULL,\n  dept VARCHAR(30) NOT NULL, age INT CHECK(age BETWEEN 0 AND 120),\n  FOREIGN KEY(dept) REFERENCES Dept(dept)\n);\nCREATE TABLE Course (\n  cno VARCHAR(4) PRIMARY KEY, cname VARCHAR(60) NOT NULL,\n  credit DECIMAL(3,1) NOT NULL CHECK(credit > 0)\n);\nCREATE TABLE SC (\n  sno VARCHAR(8), cno VARCHAR(4), grade DECIMAL(5,2) CHECK(grade BETWEEN 0 AND 100),\n  PRIMARY KEY(sno,cno),\n  FOREIGN KEY(sno) REFERENCES Student(sno),\n  FOREIGN KEY(cno) REFERENCES Course(cno)\n);"},{"title":"4. 复杂查询与视图","prompt":"查询每位学生获得的学分，保留未选课者；再建立课程平均成绩视图。","answer":"左连接保留全部学生；CASE 只累加及格课程学分。聚合输出的非聚合列写在 GROUP BY 中。视图用左连接保留尚无人选修的课程，平均分为 NULL。","checks":["保留所有学生","仅及格才计学分","未获得学分计零","视图按课程分组"],"code":"SELECT s.sno, s.sname,\n       SUM(CASE WHEN sc.grade >= 60 THEN c.credit ELSE 0 END) AS earned_credit\nFROM Student s\nLEFT JOIN SC sc ON sc.sno = s.sno\nLEFT JOIN Course c ON c.cno = sc.cno\nGROUP BY s.sno, s.sname;\n\nCREATE VIEW CourseStats AS\nSELECT c.cno, c.cname, COUNT(sc.grade) AS graded_count,\n       AVG(sc.grade) AS avg_grade\nFROM Course c LEFT JOIN SC sc ON sc.cno = c.cno\nGROUP BY c.cno, c.cname;"},{"title":"5. 带输入参数与游标的存储过程","prompt":"创建过程 print_scores，输入学号，逐行输出该学生课程号与成绩。","answer":"过程输入学号，游标查询引用该参数；使用 NOT FOUND 处理器检查 FETCH 是否到末尾，再显式关闭游标。未出分用 COALESCE 输出文字，无选课时不处理任何旧值。","checks":["过程参数类型正确","游标查询按输入学号筛选","FETCH 后先检查 done","结束后关闭游标"],"code":"DROP PROCEDURE IF EXISTS print_scores;\nDELIMITER //\nCREATE PROCEDURE print_scores(IN p_sno VARCHAR(8))\nBEGIN\nDECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_cno VARCHAR(4);\n  DECLARE v_grade DECIMAL(5,2);\n  DECLARE c_scores CURSOR FOR SELECT cno,grade FROM SC WHERE sno=p_sno ORDER BY cno;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=TRUE;\n  OPEN c_scores;\n  read_loop: LOOP\n    FETCH c_scores INTO v_cno,v_grade;\n    IF done THEN LEAVE read_loop; END IF;\n    SELECT v_cno AS cno,COALESCE(CAST(v_grade AS CHAR),'未出分') AS grade;\n  END LOOP read_loop;\n  CLOSE c_scores;\nEND //\nDELIMITER ;\nCALL print_scores('S01');"},{"title":"6. 函数、选课过程与边界","prompt":"创建返回课程平均分的函数，以及为学生选课的过程；处理重复选课，说明事务由谁提交。","answer":"AVG 忽略 NULL 成绩。复合主键保证重复选课不能插入，包括并发场景；1062 错误处理器用 SIGNAL 返回业务消息。学生或课程不存在由外键约束拒绝；过程内部不 COMMIT。","checks":["函数声明 RETURN 并返回结果","空成绩不进平均分分母","主键抵御并发重复插入","过程不擅自提交调用者事务"],"code":"DROP FUNCTION IF EXISTS course_average;\nDELIMITER //\nCREATE FUNCTION course_average(p_cno VARCHAR(4))\nRETURNS DECIMAL(6,2) READS SQL DATA\nBEGIN\nDECLARE v_avg DECIMAL(6,2);\n  SELECT AVG(grade) INTO v_avg FROM SC WHERE cno = p_cno;\n  RETURN v_avg;\nEND //\nDELIMITER ;\nDROP PROCEDURE IF EXISTS enroll;\nDELIMITER //\nCREATE PROCEDURE enroll(IN p_sno VARCHAR(8), IN p_cno VARCHAR(4))\nBEGIN\nDECLARE EXIT HANDLER FOR 1062\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='该学生已选此课程';\n  INSERT INTO SC(sno,cno,grade) VALUES(p_sno,p_cno,NULL);\nEND //\nDELIMITER ;"}]},{"id":"library-case","title":"图书借阅管理系统","label":"迁移训练","summary":"区分书目与图书副本，处理重复借阅、在借记录与历史记录。","minutes":50,"requirement":"一种书目由 ISBN 唯一标识，有书名和出版社。一种书目可有多个实体副本，副本编号唯一。读者由读者号标识。读者可多次借阅同一副本，每次有独立借阅编号，记录借出日、应还日和归还日；归还日为空表示尚未归还。","entities":[["Book","isbn · PK","title / publisher"],["Copy","copy_id · PK","isbn · FK"],["Loan","loan_id · PK","reader_id · FK / copy_id · FK"],["Reader","reader_id · PK","name"]],"relations":"Book 1 → n Copy；Reader 1 → n Loan；Copy 1 → n Loan（历史）。","tasks":[{"title":"1. 建模与码","prompt":"为什么不能只用 (reader_id,copy_id) 作为借阅记录主键？给出关系模式。","answer":"同一读者可在不同时间多次借同一副本，二元组不能唯一标识借阅事件。用独立 loan_id 作为主键。模式为 Book(isbn,title,publisher)、Copy(copy_id,isbn)、Reader(reader_id,name)、Loan(loan_id,reader_id,copy_id,borrowed_at,due_at,returned_at)。","checks":["区分书目和副本","历史记录独立编号","借阅表两个外键","明确 NULL 表示未归还"],"code":""},{"title":"2. 查询未归还与逾期","prompt":"查询截至指定日期仍未归还且已过应还日的借阅，输出读者名、书名和应还日。","answer":"同时检查 returned_at IS NULL 和 due_at 早于截止时间；日期采用 MySQL 的 ISO 字符串格式，字段类型使用 DATE 或 DATETIME。","checks":["四表连接完整","未归还用 IS NULL","正确比较应还日期","日期方言一致"],"code":"SELECT r.name, b.title, l.due_at\nFROM Loan l\nJOIN Reader r ON r.reader_id = l.reader_id\nJOIN Copy cp ON cp.copy_id = l.copy_id\nJOIN Book b ON b.isbn = cp.isbn\nWHERE l.returned_at IS NULL\n  AND l.due_at \u003c '2026-11-16';"},{"title":"3. 统计所有读者的在借数量","prompt":"包括当前没有在借记录的读者，输出 reader_id、name 和在借数量。","answer":"把未归还条件放入 ON，保留读者；COUNT(l.loan_id) 统计实际匹配行。","checks":["LEFT JOIN 的方向正确","条件位于 ON","COUNT 非空主键","非聚合列分组"],"code":"SELECT r.reader_id, r.name, COUNT(l.loan_id) AS active_count\nFROM Reader r\nLEFT JOIN Loan l ON l.reader_id = r.reader_id\n AND l.returned_at IS NULL\nGROUP BY r.reader_id, r.name;"},{"title":"4. 归还过程与异常","prompt":"创建 return_copy(p_loan_id)，只归还尚未归还的记录；若没有更新任何行则抛出业务异常。","answer":"有条件 UPDATE 只修改尚未归还的记录；立即检查 ROW_COUNT()。若没有改变任何行，使用 SIGNAL 抛出业务错误；过程不自行提交。","checks":["仅更新未归还记录","NOW() 记录归还时间","立即检查 ROW_COUNT()","零行使用 SIGNAL 报错"],"code":"DROP PROCEDURE IF EXISTS return_copy;\nDELIMITER //\nCREATE PROCEDURE return_copy(IN p_loan_id INT)\nBEGIN\nUPDATE Loan SET returned_at=NOW()\n  WHERE loan_id=p_loan_id AND returned_at IS NULL;\n  IF ROW_COUNT()=0 THEN\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='借阅记录不存在或已经归还';\n  END IF;\nEND //\nDELIMITER ;"}]},{"id":"employee-case","title":"部门员工与薪资审计","label":"编程强化","summary":"练习部门加薪、平均薪资函数和逐行审计触发器。","minutes":45,"requirement":"每位员工仅属于一个部门，部门可以有多位员工。员工有员工号、姓名、工资；工资非空且非负。给定部门和比例，为该部门全部员工加薪；工资变更需要记录修改前后的值及时间。使用 Department(dno,dname)、Employee(eno,ename,dno,salary)。","entities":[["Department","dno · PK","dname"],["Employee","eno · PK","ename / dno · FK / salary"],["SalaryAudit","eno","old_salary / new_salary / changed_at"]],"relations":"Department 1 → n Employee；Employee 的工资变化产生审计行。","tasks":[{"title":"1. 表结构与范式","prompt":"列出主键、外键与主要函数依赖，解释为何不把部门名称重复写在每个员工行上。","answer":"Department 的主键为 dno；Employee 主键为 eno，dno 是外键。依赖为 dno→dname；eno→ename,dno,salary。若把 dname 放 Employee，会有 eno→dno→dname 的非主属性传递依赖。","checks":["主键与外键正确","写出函数依赖","识别传递依赖","工资 NOT NULL 且 CHECK 非负"],"code":""},{"title":"2. 加薪过程","prompt":"输入部门号和加薪比例，例如 0.15 代表 15%；用集合式 SQL 完成更新并输出影响行数。","answer":"用集合式 UPDATE 给指定部门加薪；先验证比例非空非负。更新后立即保存 ROW_COUNT()，再输出影响行数；不在过程中提交事务。","checks":["比例非空非负","关联输入部门","ROUND 到两位小数","输出影响行数"],"code":"DROP PROCEDURE IF EXISTS raise_salary;\nDELIMITER //\nCREATE PROCEDURE raise_salary(IN p_dno VARCHAR(8), IN p_rate DECIMAL(6,4))\nBEGIN\nDECLARE v_changed INT;\n  IF p_rate IS NULL OR p_rate\u003c0 THEN\n    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='加薪比例必须非空且非负';\n  END IF;\n  UPDATE Employee SET salary=ROUND(salary*(1+p_rate),2) WHERE dno=p_dno;\n  SET v_changed=ROW_COUNT();\n  SELECT v_changed AS changed_rows;\nEND //\nDELIMITER ;"},{"title":"3. 返回平均薪资","prompt":"创建函数 avg_salary，输入部门号，返回部门平均工资。没有员工时返回 NULL。","answer":"使用 AVG；不将不存在的平均工资悄悄当成 0。","checks":["输入参数类型正确","AVG 的范围正确","RETURNS 类型及结果","不错误捕获聚合零行"],"code":"DROP FUNCTION IF EXISTS avg_salary;\nDELIMITER //\nCREATE FUNCTION avg_salary(p_dno VARCHAR(8))\nRETURNS DECIMAL(12,2) READS SQL DATA\nBEGIN\nDECLARE v_avg DECIMAL(12,2);\n  SELECT AVG(salary) INTO v_avg FROM Employee WHERE dno=p_dno;\n  RETURN v_avg;\nEND //\nDELIMITER ;"},{"title":"4. 薪资审计触发器","prompt":"建立审计表，并在工资真实发生变化时写入旧值、新值和时间。","answer":"使用 AFTER UPDATE ON Employee FOR EACH ROW，并在程序体内比较 OLD.salary 与 NEW.salary。NULL 安全比较跳过没有真实变化的更新。审计与工资更新属于同一 InnoDB 事务。","checks":["AFTER UPDATE ON Employee","FOR EACH ROW","OLD/NEW 与 NOW() 使用正确","只记录真实变化，原事务回滚时审计也回滚"],"code":"CREATE TABLE SalaryAudit (\n  eno VARCHAR(8), old_salary DECIMAL(12,2),\n  new_salary DECIMAL(12,2), changed_at DATETIME\n);\nDELIMITER //\nCREATE TRIGGER trg_salary_audit\nAFTER UPDATE ON Employee\nFOR EACH ROW\nBEGIN\n  IF NOT (OLD.salary \u003c=> NEW.salary) THEN\n    INSERT INTO SalaryAudit(eno,old_salary,new_salary,changed_at)\n    VALUES(NEW.eno,OLD.salary,NEW.salary,NOW());\n  END IF;\nEND //\nDELIMITER ;"}]}],"homework":[{"id":"hw4","title":"上机 4 · 基建与快递管理","label":"建模与多表查询","summary":"项目供需、分组筛选、集合差，以及快递单约束和外连接。","minutes":65,"dialect":"MySQL 8.0.16+","schemas":["construction","parcel"],"requirement":"基建系统包含项目、供应商、原材料、供需四个模块。快递系统需要区分人员与快件，同一个人可以兼任寄件人与收件人。基建练习按“每个供应商供应一种原材料”建模；每个项目、供应商、材料组合只保留一条汇总数量记录。","tasks":[{"title":"基建 1 · 项目名称模糊查询","prompt":"查询项目名中包含“南京”的项目的所有供需信息。","answer":"题目筛选的是项目名称，而不是项目地址。项目名与地址即使恰好相同，也不能互换筛选字段。","code":"SELECT p.*, s.s_number, s.s_name, m.*, pr.pr_count\nFROM projects p\nJOIN provides pr ON pr.pr_p_number = p.p_number\nJOIN suppliers s ON s.s_number = pr.pr_s_number\nJOIN materials m ON m.m_number = pr.pr_m_number\nWHERE p.p_name LIKE '%南京%';","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"基建 2 · 至少三种且每种数量达标","prompt":"查询至少需要 3 种不同原材料，且每种原材料的供应数量不低于 10 的项目编号与名称。","answer":"先按项目和材料汇总多供应商的供货数量，再按项目检查材料种数及各材料数量最小值。“每种不低于 10”不能只筛掉不足 10 的材料后再统计，否则会漏检不合格材料。","code":"SELECT p.p_number, p.p_name\nFROM projects p\nJOIN (\n  SELECT pr_p_number, pr_m_number, SUM(pr_count) AS material_qty\n  FROM provides GROUP BY pr_p_number, pr_m_number\n) x ON x.pr_p_number = p.p_number\nGROUP BY p.p_number, p.p_name\nHAVING COUNT(*) >= 3 AND MIN(x.material_qty) >= 10;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"基建 3 · 使用 A 但没有使用 B","prompt":"查询使用了“材料1”但没有使用“材料2”的项目编号和名称。","answer":"用一个 EXISTS 检查有材料1，再用 NOT EXISTS 排除任何材料2。不能只写材料名不等于材料2，因为同一项目还可能有另一条材料2的供需记录。","code":"SELECT p.p_number,p.p_name FROM projects p\nWHERE EXISTS (\n  SELECT 1 FROM provides pr JOIN materials m ON m.m_number=pr.pr_m_number\n  WHERE pr.pr_p_number=p.p_number AND m.m_name='材料1'\n) AND NOT EXISTS (\n  SELECT 1 FROM provides pr JOIN materials m ON m.m_number=pr.pr_m_number\n  WHERE pr.pr_p_number=p.p_number AND m.m_name='材料2'\n);","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"基建 4 · 供应商信息","prompt":"查询所有供应商的信息。","answer":"若只要供应商表字段，无需连接供需表；连接会让有多条供需记录的供应商重复。","code":"SELECT * FROM suppliers;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"快递 1 · 主外键与单号约束","prompt":"创建快递管理表，包含主外键。快递单号必须唯一、长度为 10 且以“2301”开始；寄件日期默认为当前日期。","answer":"人员只存一份，parcels 的 sender_id 和 receiver_id 两个外键分别表达角色；同一个人可以同时出现在两种角色中。单号长度与前缀由 CHECK 约束。完整脚本含建表与样例数据。","code":"-- MySQL 8.0.16+\nCREATE TABLE people (\n person_id INT PRIMARY KEY, person_name VARCHAR(50) NOT NULL,\n phone VARCHAR(20), address VARCHAR(100), postcode VARCHAR(10)\n);\nCREATE TABLE companies (company_id INT PRIMARY KEY, company_name VARCHAR(30) NOT NULL);\nCREATE TABLE parcels (\n parcel_no VARCHAR(10) PRIMARY KEY,\n company_id INT NOT NULL,\n sender_id INT NOT NULL, receiver_id INT NOT NULL,\n pickup_code VARCHAR(20), logistics VARCHAR(200),\n collected BOOLEAN NOT NULL DEFAULT FALSE,\n sent_date DATE NOT NULL DEFAULT (CURRENT_DATE),\n CHECK(CHAR_LENGTH(parcel_no)=10 AND BINARY LEFT(parcel_no,4)=BINARY '2301'),\n FOREIGN KEY(company_id) REFERENCES companies(company_id),\n FOREIGN KEY(sender_id) REFERENCES people(person_id),\n FOREIGN KEY(receiver_id) REFERENCES people(person_id)\n);\nINSERT INTO people VALUES(1,'学习者A','13800000001','南京东苑','210000'),(2,'学习者B','13800000002','南京西苑','210001'),(3,'学习者C','13800000003','常州','213000');\nINSERT INTO companies VALUES(1,'顺丰'),(2,'中通'),(3,'圆通'),(4,'韵达');\nINSERT INTO parcels(parcel_no,company_id,sender_id,receiver_id,pickup_code,logistics) VALUES('2301000001',1,1,2,'1-001','已到代收点'),('2301000002',2,2,1,'2-001','运输中');\n","checks":["人员、公司、快件三类对象完整","单号主键与长度前缀约束正确","两个角色外键均引用人员","日期默认值的 MySQL 版本符合要求"],"dataset":"parcel"},{"title":"快递 2 · 各公司快件数量","prompt":"查询顺丰、中通、圆通、韵达等各快递公司的快件数量。","answer":"从公司表 LEFT JOIN 快件表，可显示零快件的公司；COUNT(parcel_no) 不计空补齐行。","code":"SELECT c.company_name,COUNT(p.parcel_no) AS parcel_count\nFROM companies c LEFT JOIN parcels p ON p.company_id=c.company_id\nGROUP BY c.company_id,c.company_name;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"parcel"},{"title":"快递 3 · 包含尚未寄件的人员","prompt":"查询所有寄件人的信息，如果他没有寄件也要包含他的信息。","answer":"这里把所有已登记人员视作潜在寄件人。若要显示快件信息，用 LEFT JOIN；如果只要人员基本资料，直接查询 people 即可。","code":"SELECT pe.*,p.parcel_no,p.sent_date\nFROM people pe LEFT JOIN parcels p ON p.sender_id=pe.person_id;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"parcel"}]},{"id":"hw5","title":"上机 5 · 销售管理系统","label":"约束与汇总视图","summary":"客户、订单、库存、产品四表关联，练习价格统计与销量最高视图。","minutes":50,"dialect":"MySQL 8.0.16+","schemas":["sales"],"requirement":"系统包含客户、订单、库存和产品。货号必须是 10 个字符且以 DYKJ 开始，订单日期默认当前日期。练习采用一张订单记录对应一种产品的简化模型；若一张订单包含多种产品，应再分订单头与明细。","tasks":[{"title":"1 · 建表并插入样例数据","prompt":"用 SQL 创建表格，设置主外键；货号为 10 个字符且以“DYKJ”开始；订单日期默认为当前日期，并插入数据。","answer":"产品单价用 DECIMAL，数量用整数，日期使用 ISO 格式。数据中的“货号1”等简写替换为满足长度与前缀要求的正式编号。","code":"-- MySQL 8.0.16+\nCREATE TABLE customers(c_num VARCHAR(20) PRIMARY KEY,c_name VARCHAR(60) NOT NULL,c_add VARCHAR(100),c_duty VARCHAR(30));\nCREATE TABLE products(\n p_num VARCHAR(10) PRIMARY KEY,p_name VARCHAR(60) NOT NULL,\n p_model VARCHAR(30),p_price DECIMAL(10,2) NOT NULL CHECK(p_price>=0),\n CHECK(CHAR_LENGTH(p_num)=10 AND BINARY LEFT(p_num,4)=BINARY 'DYKJ')\n);\nCREATE TABLE stocks(p_num VARCHAR(10) PRIMARY KEY,stock_count INT NOT NULL CHECK(stock_count>=0),place VARCHAR(50),FOREIGN KEY(p_num) REFERENCES products(p_num));\nCREATE TABLE sales_orders(\n o_num VARCHAR(20) PRIMARY KEY,o_time DATE NOT NULL DEFAULT (CURRENT_DATE),\n c_num VARCHAR(20) NOT NULL,p_num VARCHAR(10) NOT NULL,\n quantity INT NOT NULL CHECK(quantity>0),\n FOREIGN KEY(c_num) REFERENCES customers(c_num),FOREIGN KEY(p_num) REFERENCES products(p_num)\n);\nINSERT INTO customers VALUES('k001','学习者','东苑','001001001'),('k002','张三','东苑','002002002'),('k003','客户A','西苑','003003003');\nINSERT INTO products VALUES('DYKJ000001','材料1','重型',20),('DYKJ000002','材料2','轻型',10),('DYKJ000003','材料3','中型',5);\nINSERT INTO stocks VALUES('DYKJ000001',100,'x1'),('DYKJ000002',200,'x2'),('DYKJ000003',100,'x3');\nINSERT INTO sales_orders VALUES('D001','2024-11-01','k001','DYKJ000001',30),('D002','2024-11-02','k001','DYKJ000002',40),('D003','2024-11-05','k002','DYKJ000001',50),('D004','2024-11-01','k003','DYKJ000002',20);\n","checks":["四个模块及主外键完整","货号长度与前缀约束","日期默认值正确","先插父表，再插订单和库存"],"dataset":"sales"},{"title":"2 · 所有客户相关信息","prompt":"查询所有客户的所有相关信息。","answer":"若只要求基本信息，可直接 SELECT * FROM customers；若“相关信息”包含订单、产品、库存，则使用多层 LEFT JOIN 保留未下单客户。以下给出后一种解释。","code":"SELECT c.*,o.o_num,o.o_time,o.quantity,p.p_num,p.p_name,p.p_price,\n       s.stock_count,s.place\nFROM customers c\nLEFT JOIN sales_orders o ON o.c_num=c.c_num\nLEFT JOIN products p ON p.p_num=o.p_num\nLEFT JOIN stocks s ON s.p_num=p.p_num;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"sales"},{"title":"3 · 客户A已购产品价格","prompt":"查询客户名为“客户A”的客户所有已购买产品的平均价格、最高价格和最低价格。","answer":"这里按“购买过的不同产品”的当前单价统计，使用 EXISTS 避免同一产品多次下单造成重复计权。如果题目要求按销量加权平均，应另算 SUM(单价×数量)/SUM(数量)。","code":"SELECT AVG(p.p_price) AS avg_price,MAX(p.p_price) AS max_price,\n       MIN(p.p_price) AS min_price\nFROM products p\nWHERE EXISTS (\n SELECT 1 FROM sales_orders o JOIN customers c ON c.c_num=o.c_num\n WHERE o.p_num=p.p_num AND c.c_name='客户A'\n);","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"sales"},{"title":"4 · 时间段订单","prompt":"查询某个时间段内提交的所有订单信息。","answer":"示例查询 2024 年 11 月 1 日到 4 日。使用左闭右开边界，若将 DATE 升级到 DATETIME，也能保留结束日的全部时间。","code":"SELECT * FROM sales_orders\nWHERE o_time >= '2024-11-01' AND o_time \u003c '2024-11-05';","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"sales"},{"title":"5 · 总销量最高的产品视图","prompt":"创建一个视图，显示销售数量最多的产品信息及其库存数。","answer":"先按产品 SUM(quantity) 得到总销量，再找最高总销量；DENSE_RANK 保留所有并列第一。不能按某一笔订单的最大数量代替产品总销量。","code":"CREATE VIEW top_selling_products AS\nSELECT p_num,p_name,p_model,p_price,stock_count,sold_qty\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY sold_qty DESC) AS rnk\n  FROM (\n    SELECT p.p_num,p.p_name,p.p_model,p.p_price,\n      COALESCE(s.stock_count,0) AS stock_count,SUM(o.quantity) AS sold_qty\n    FROM products p JOIN sales_orders o ON o.p_num=p.p_num\n    LEFT JOIN stocks s ON s.p_num=p.p_num\n    GROUP BY p.p_num,p.p_name,p.p_model,p.p_price,s.stock_count\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"sales"}]},{"id":"hw6","title":"上机 6 · 图书借阅与游标","label":"统计视图与逐行处理","summary":"区分借阅次数、总本数、单次本数与种类数，再用游标处理库存和到期提醒。","minutes":100,"dialect":"MySQL 8.0.16+","schemas":["library","construction"],"requirement":"图书库存按种类记录。一个借阅事件可有多种图书，每种可借多本；借阅状态包括已完成、进行中、未借阅。借阅统计只计已完成和进行中。视图中的“最多”保留全部并列结果。第 16 题切换到基建数据集。","tasks":[{"title":"1 · 图书借阅建模与约束","prompt":"创建表格并设置主外键；借书证号唯一、长度为 10 且以“1901”开始；性别限“男”“女”，插入数据。一个人一次可借多本、多种类。","answer":"把“借阅事件”与“每种类明细”分开：borrow 一行代表一次借阅，borrow_items 一行代表该次的一种图书。这样借阅次数、总本数与单次种类数均可准确统计。应还时间 due_at 用于临近到期提醒。演示姓名“学习者”可换为自己姓名。","code":"-- MySQL 8.0.16+；一次借阅可含多个种类，因此分开借阅事件和明细。\nCREATE TABLE books(b_category VARCHAR(30) PRIMARY KEY,b_count INT NOT NULL CHECK(b_count>=0),b_position VARCHAR(60));\nCREATE TABLE people(\n p_number VARCHAR(10) PRIMARY KEY,p_name VARCHAR(40) NOT NULL,\n p_sex VARCHAR(2) NOT NULL CHECK(p_sex IN ('男','女')),\n CHECK(CHAR_LENGTH(p_number)=10 AND BINARY LEFT(p_number,4)=BINARY '1901')\n);\nCREATE TABLE borrow(\n borrow_id INT PRIMARY KEY,p_number VARCHAR(10) NOT NULL,\n borrowed_at DATETIME NOT NULL,due_at DATETIME NOT NULL,returned_at DATETIME,\n borrow_state VARCHAR(6) NOT NULL CHECK(borrow_state IN ('已完成','进行中','未借阅')),\n FOREIGN KEY(p_number) REFERENCES people(p_number),\n CHECK(due_at>=borrowed_at)\n);\nCREATE TABLE borrow_items(\n borrow_id INT,b_category VARCHAR(30),quantity INT NOT NULL CHECK(quantity>0),\n PRIMARY KEY(borrow_id,b_category),\n FOREIGN KEY(borrow_id) REFERENCES borrow(borrow_id),\n FOREIGN KEY(b_category) REFERENCES books(b_category)\n);\nINSERT INTO books VALUES('哲学类',20,'位置1'),('社会科学',10,'位置2'),('财经管理',30,'位置3'),('历史地理',5,'位置4'),('文化教育',16,'位置5'),('自然科学',7,'位置6');\nINSERT INTO people VALUES('1901000001','学习者','男'),('1901000002','借阅人B','女'),('1901000003','借阅人C','男');\nINSERT INTO borrow VALUES(1,'1901000001','2026-11-01 09:00:00','2026-11-17 09:00:00',NULL,'进行中'),(2,'1901000001','2026-10-14 09:00:00','2026-11-05 09:00:00','2026-11-01 10:00:00','已完成'),(3,'1901000002','2026-09-14 09:00:00','2026-09-30 09:00:00','2026-09-28 10:00:00','已完成');\nINSERT INTO borrow_items VALUES(1,'哲学类',2),(1,'历史地理',1),(2,'历史地理',1),(3,'历史地理',3),(3,'自然科学',2);\n","checks":["借阅事件和种类明细分离","借书证号主键及格式正确","性别非空且受限","主外键、数量与应还时间完整"],"dataset":"library"},{"title":"2 · 各种类图书库存","prompt":"查询各种种类图书数量，包括哲学类、社会科学、财经管理、历史地理、文化教育、自然科学等。","answer":"books 保存当前库存数量，直接查询即可。借阅数量与库存不是同一个统计。","code":"SELECT b_category,b_count,b_position FROM books;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"3 · 总借阅次数最多的图书种类","prompt":"创建视图，查询总借阅次数最多的图书种类。","answer":"一次借阅同一种类有多本，仍只算一次。未借阅状态不计入实际借阅。 视图保留全部并列最大结果。","code":"CREATE VIEW top_category_visits AS\nSELECT b_category,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT i.b_category,COUNT(DISTINCT b.borrow_id) AS n\n    FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY i.b_category\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"4 · 总借阅次数最多的借阅人","prompt":"创建视图，查询总借阅次数最多的借阅人。","answer":"按借阅事件去重，不要把一次借阅的多种类明细算成多次。 视图保留全部并列最大结果。","code":"CREATE VIEW top_reader_visits AS\nSELECT p_number,p_name,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT p.p_number,p.p_name,COUNT(b.borrow_id) AS n\n    FROM people p JOIN borrow b ON b.p_number=p.p_number\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY p.p_number,p.p_name\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"5 · 总借阅本数最多的图书种类","prompt":"创建视图，查询总借阅本数最多的图书种类。","answer":"本数使用 SUM(quantity)，次数使用 COUNT，二者需要区分。 视图保留全部并列最大结果。","code":"CREATE VIEW top_category_books AS\nSELECT b_category,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT i.b_category,SUM(i.quantity) AS n\n    FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY i.b_category\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"6 · 总借阅本数最多的借阅人","prompt":"创建视图，查询总借阅本数最多的借阅人。","answer":"把某人的各次借阅、各明细本数相加，再比较最大值。 视图保留全部并列最大结果。","code":"CREATE VIEW top_reader_books AS\nSELECT p_number,p_name,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT p.p_number,p.p_name,SUM(i.quantity) AS n\n    FROM people p JOIN borrow b ON b.p_number=p.p_number\n    JOIN borrow_items i ON i.borrow_id=b.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY p.p_number,p.p_name\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"7 · 单次借阅本数最多的借阅人","prompt":"创建视图，查询单次借阅本数最多的借阅人。","answer":"先按一次借阅汇总所有种类的本数，再在借阅事件之间比较；保留借阅编号以展示是哪一次。 视图保留全部并列最大结果。","code":"CREATE VIEW top_single_reader_books AS\nSELECT p_number,p_name,borrow_id,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT p.p_number,p.p_name,b.borrow_id,SUM(i.quantity) AS n\n    FROM people p JOIN borrow b ON b.p_number=p.p_number\n    JOIN borrow_items i ON i.borrow_id=b.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY p.p_number,p.p_name,b.borrow_id\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"8 · 单次借阅本数最多的图书种类","prompt":"创建视图，查询单次借阅本数最多的图书种类。","answer":"将“单次某种类本数”理解为一次借阅事件中该种类的 quantity，找最大明细本数。如果要求的是“最大总本数那次包含哪些种类”，则应先找事件总本数最大值，再连接其全部明细。 视图保留全部并列最大结果。","code":"CREATE VIEW top_single_category_books AS\nSELECT borrow_id,b_category,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT i.borrow_id,i.b_category,i.quantity AS n\n    FROM borrow_items i JOIN borrow b ON b.borrow_id=i.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中')\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"9 · 单次借阅种类最多的借阅人","prompt":"创建视图，查询单次借阅种类最多的借阅人。","answer":"按借阅事件 COUNT(DISTINCT b_category)，比较种类数，不是比较本数。 视图保留全部并列最大结果。","code":"CREATE VIEW top_single_reader_categories AS\nSELECT p_number,p_name,borrow_id,n\nFROM (\n  SELECT b.*, DENSE_RANK() OVER(ORDER BY n DESC) AS rnk\n  FROM (\n    SELECT p.p_number,p.p_name,b.borrow_id,COUNT(DISTINCT i.b_category) AS n\n    FROM people p JOIN borrow b ON b.p_number=p.p_number\n    JOIN borrow_items i ON i.borrow_id=b.borrow_id\n    WHERE b.borrow_state IN ('已完成','进行中') GROUP BY p.p_number,p.p_name,b.borrow_id\n  ) b\n) ranked\nWHERE rnk = 1;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"10 · 自己已完成的借阅","prompt":"查询姓名为“自己名字”的用户所有已完成，即借书且已经还书的借阅信息。","answer":"用可替换的 @reader_name 参数。按证号关联以区分同名读者；若可能重名，应直接输入借书证号。","code":"SET @reader_name='学习者';\nSELECT p.p_number,p.p_name,b.*,i.b_category,i.quantity\nFROM people p JOIN borrow b ON b.p_number=p.p_number\nJOIN borrow_items i ON i.borrow_id=b.borrow_id\nWHERE p.p_name=@reader_name AND b.borrow_state='已完成';","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"11 · 包含没有借书的借阅人","prompt":"查询所有借阅人信息，如果没有借书也要包含。","answer":"从 people 开始左连接 borrow 与明细。若只需要借阅人基本信息，直接查询 people。","code":"SELECT p.*,b.borrow_id,b.borrow_state,i.b_category,i.quantity\nFROM people p LEFT JOIN borrow b ON b.p_number=p.p_number\nLEFT JOIN borrow_items i ON i.borrow_id=b.borrow_id;","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"12 · 时间段内借阅记录","prompt":"查询某个时间段所有借阅信息，包含已完成、进行中。","answer":"条件同时包含借出时间与状态集合。左闭右开区间避免遗漏结束日时间部分。","code":"SELECT b.*,i.b_category,i.quantity\nFROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id\nWHERE b.borrowed_at >= '2026-10-01' AND b.borrowed_at \u003c '2026-12-01'\n  AND b.borrow_state IN ('已完成','进行中');","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"13 · 游标检查图书库存","prompt":"创建游标，查询所有图书库存；少于 3 本时输出“此图书需要补充库存！”。","answer":"MySQL 的游标放在存储过程内。按“变量→游标→处理器”顺序声明，FETCH 后检查 done 再使用变量。","code":"DROP PROCEDURE IF EXISTS check_book_stock;\nDELIMITER //\nCREATE PROCEDURE check_book_stock()\nBEGIN\n  DECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_category VARCHAR(30);\n  DECLARE v_count INT;\n  DECLARE cur CURSOR FOR SELECT b_category,b_count FROM books;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n  OPEN cur;\n  read_loop: LOOP\n    FETCH cur INTO v_category,v_count;\n    IF done THEN LEAVE read_loop; END IF;\n    IF v_count\u003c3 THEN\n      SELECT CONCAT(v_category,'此图书需要补充库存！') AS message;\n    END IF;\n  END LOOP;\n  CLOSE cur;\nEND //\nDELIMITER ;\nCALL check_book_stock();","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"14 · 游标提醒未归还","prompt":"创建游标，查询所有图书借阅情况；未归还时输出“此图书需要归还！”。","answer":"使用进行中且 returned_at IS NULL 判定未归还，再连接明细以按种类提醒。","code":"DROP PROCEDURE IF EXISTS check_unreturned;\nDELIMITER //\nCREATE PROCEDURE check_unreturned()\nBEGIN\n  DECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_category VARCHAR(30);\n  DECLARE cur CURSOR FOR SELECT i.b_category FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id WHERE b.borrow_state='进行中' AND b.returned_at IS NULL;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n  OPEN cur;\n  read_loop: LOOP\n    FETCH cur INTO v_category;\n    IF done THEN LEAVE read_loop; END IF;\n    SELECT CONCAT(v_category,'此图书需要归还！') AS message;\n  END LOOP;\n  CLOSE cur;\nEND //\nDELIMITER ;\nCALL check_unreturned();","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"15 · 游标提醒距离到期不足一天","prompt":"创建游标，未归还且距离应还时间不足 1 天时，输出“此图书距离归还不到1天！”。","answer":"此处将“时间小于1天”解释为尚未到期、剩余时间小于一天；due_at 必须存在。已逾期应另做提醒。若题目意指借出时长不足一天，应改为 borrowed_at > NOW()-INTERVAL 1 DAY。","code":"DROP PROCEDURE IF EXISTS check_due_soon;\nDELIMITER //\nCREATE PROCEDURE check_due_soon()\nBEGIN\n  DECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_category VARCHAR(30);\n  DECLARE cur CURSOR FOR SELECT i.b_category FROM borrow b JOIN borrow_items i ON i.borrow_id=b.borrow_id WHERE b.borrow_state='进行中' AND b.returned_at IS NULL AND b.due_at>NOW() AND b.due_at\u003cNOW()+INTERVAL 1 DAY;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n  OPEN cur;\n  read_loop: LOOP\n    FETCH cur INTO v_category;\n    IF done THEN LEAVE read_loop; END IF;\n    SELECT CONCAT(v_category,'此图书距离归还不到1天！') AS message;\n  END LOOP;\n  CLOSE cur;\nEND //\nDELIMITER ;\nCALL check_due_soon();","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"library"},{"title":"16 · 游标检查原材料库存","prompt":"基建管理系统中，创建游标查询所有原料库存；库存数小于等于 2 时，输出“XXX（原料名）需要补充库存！”。","answer":"使用 construction 数据集，注意本题阈值是 \u003c=2，与图书题的 \u003c3 表达等价，但应忠实写出各自条件。","code":"DROP PROCEDURE IF EXISTS check_material_stock;\nDELIMITER //\nCREATE PROCEDURE check_material_stock()\nBEGIN\n  DECLARE done BOOLEAN DEFAULT FALSE;\n  DECLARE v_name VARCHAR(60);\n  DECLARE v_count INT;\n  DECLARE cur CURSOR FOR SELECT m_name,m_put_count FROM materials;\n  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;\n  OPEN cur;\n  read_loop: LOOP\n    FETCH cur INTO v_name,v_count;\n    IF done THEN LEAVE read_loop; END IF;\n    IF v_count\u003c=2 THEN\n      SELECT CONCAT(v_name,'需要补充库存！') AS message;\n    END IF;\n  END LOOP;\n  CLOSE cur;\nEND //\nDELIMITER ;\nCALL check_material_stock();","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"}]},{"id":"hw78","title":"上机 7–8 · 存储过程与函数","label":"业务编程","summary":"基建项目材料统计、返回材料信息，以及电商供应商模糊查询和购物车排序。","minutes":60,"dialect":"MySQL 8.0.16+","schemas":["construction","ecommerce"],"requirement":"基建系统沿用项目、供应商、原材料与供需表。电商系统包含用户、商品、供应商、订单与购物车。本组使用 MySQL 存储程序，函数返回 JSON 数组表达可能的多条供需记录。","tasks":[{"title":"基建 1 · 按项目名称统计材料种数","prompt":"创建存储过程，输入项目名称 ZZZ，打印“ZZZ项目共需要X种原材料”；未找到项目时打印“ZZZ项目还没有记录”。","answer":"先检查项目是否存在。存在但没有供需记录时，COUNT(DISTINCT) 得到 0；项目不存在才输出未记录。同名项目按输入名称汇总，若要求单一项目，建议改传项目编号。","code":"DROP PROCEDURE IF EXISTS project_material_count;\nDELIMITER //\nCREATE PROCEDURE project_material_count(IN p_project_name VARCHAR(60))\nBEGIN\n  DECLARE v_count INT;\n  IF EXISTS(SELECT 1 FROM projects WHERE p_name=p_project_name) THEN\n    SELECT COUNT(DISTINCT pr.pr_m_number) INTO v_count\n    FROM projects p LEFT JOIN provides pr ON pr.pr_p_number=p.p_number\n    WHERE p.p_name=p_project_name;\n    SELECT CONCAT(p_project_name,'项目共需要',v_count,'种原材料') AS message;\n  ELSE\n    SELECT CONCAT(p_project_name,'项目还没有记录') AS message;\n  END IF;\nEND //\nDELIMITER ;\nCALL project_material_count('南京甲');","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"基建 2 · 返回项目原材料信息","prompt":"创建存储函数，查询“南京甲”所需“原材料A”的所有信息，至少包含项目名、原材料名、单价、供应数量。","answer":"MySQL 函数不能直接返回普通多行 SELECT 结果集。这里用 JSON_ARRAYAGG 将供需记录组合为 JSON 数组，无记录时返回 []。函数参数是输入参数，RETURNS JSON 声明返回类型；读取表时声明 READS SQL DATA。","code":"DROP FUNCTION IF EXISTS project_material_info;\nDELIMITER //\nCREATE FUNCTION project_material_info(p_project_name VARCHAR(60),p_material_name VARCHAR(60))\nRETURNS JSON READS SQL DATA\nBEGIN\n  DECLARE v_result JSON;\n  SELECT JSON_ARRAYAGG(JSON_OBJECT(\n    '项目名',p.p_name,'原材料名',m.m_name,\n    '原材料单价',m.m_price,'供应商',pr.pr_s_number,'供应数量',pr.pr_count\n  )) INTO v_result\n  FROM projects p JOIN provides pr ON pr.pr_p_number=p.p_number\n  JOIN materials m ON m.m_number=pr.pr_m_number\n  WHERE p.p_name=p_project_name AND m.m_name=p_material_name;\n  RETURN COALESCE(v_result,JSON_ARRAY());\nEND //\nDELIMITER ;\nSELECT project_material_info('南京甲','原材料A');","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"construction"},{"title":"电商 1 · 商品名称模糊查询供应商","prompt":"创建存储过程，输入商品名称（模糊），输出提供相关商品的供应商数量；无匹配时输出“没有供应商提供XXX商品”。","answer":"同一供应商可能有多个匹配商品，使用 COUNT(DISTINCT s_id)。输入作为包含匹配；用户输入的 % 和 _ 在该写法中也保留通配符含义。","code":"DROP PROCEDURE IF EXISTS find_suppliers;\nDELIMITER //\nCREATE PROCEDURE find_suppliers(IN p_keyword VARCHAR(60))\nBEGIN\n  DECLARE v_count INT;\n  SELECT COUNT(DISTINCT s.s_id) INTO v_count\n  FROM suppliers s JOIN products p ON p.s_id=s.s_id\n  WHERE p.p_name LIKE CONCAT('%',p_keyword,'%');\n  IF v_count>0 THEN\n    SELECT CONCAT('共找到',v_count,'个供应商提供',p_keyword,'商品!') AS message;\n  ELSE\n    SELECT CONCAT('没有供应商提供',p_keyword,'商品') AS message;\n  END IF;\nEND //\nDELIMITER ;\nCALL find_suppliers('手机');","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"ecommerce"},{"title":"电商 2 · 购物车按加入时间降序","prompt":"创建存储过程，查询某位用户的购物车商品信息，并按商品添加时间降序。","answer":"输入用户编号，关联购物车与商品。按 added_at DESC 排序；同一时间用 p_id 提供稳定次序。","code":"DROP PROCEDURE IF EXISTS show_cart;\nDELIMITER //\nCREATE PROCEDURE show_cart(IN p_user_id INT)\nBEGIN\n  SELECT p.p_id,p.p_name,p.price,c.quantity,c.added_at\n  FROM cart c JOIN products p ON p.p_id=c.p_id\n  WHERE c.u_id=p_user_id\n  ORDER BY c.added_at DESC,c.p_id ASC;\nEND //\nDELIMITER ;\nCALL show_cart(1);","checks":["字段、连接与过滤条件符合题意","注意空值、重复与并列结果","使用当前题组对应的数据库方言"],"dataset":"ecommerce"}]}]};
